# ACTION TOOL 8 — email_invoice
# ══════════════════════════════════════════════════════════════════════════════

def _load_payment_settings() -> dict:
    """
    Reads payment-link settings from the main config.json in one shot: the
    Stripe/Square credentials and any configured static fallback URLs
    (Small Business tab), plus the two independent enable/disable toggles
    added alongside them. Shared by email_invoice()'s HTML body injection
    and its SMS companion message — both channels are gated separately,
    since "safe to put a payment link in an email" and "safe to put one
    in an SMS" are genuinely different questions (SMS is far more exposed
    to carrier filtering and toll-free registration requirements).

    Xero is intentionally NOT supported — its API requires full OAuth 2.0
    (registered redirect URI, access + refresh token management, a
    per-organization tenant ID), a fundamentally heavier integration than
    Stripe's Secret Key or Square's Access Token. Judged too complex for
    this feature's target users; a static Xero link was previously
    offered but has been removed rather than left half-supported.

    Personal and server mode read the exact same config.json location —
    no mode-specific branching needed here, unlike several other settings
    this project has had to special-case for server mode. In server mode
    this is deliberately an OWNER-level credential (same pattern as SMTP):
    configured once by the owner/admin, then any role's email_invoice()
    call uses it automatically — a field crew member never sees or needs
    their own Stripe/Square account.
    """
    import json as _jspay, pathlib as _plpay
    try:
        _main_cfg = _jspay.loads(
            (_plpay.Path.home() / ".ai-prowler" / "config.json")
            .read_text(encoding="utf-8"))
    except Exception:
        _main_cfg = {}
    return {
        "stripe_secret_key":   _main_cfg.get("stripe_secret_key", "").strip(),
        "stripe_fallback_url": _main_cfg.get("stripe_payment_url", "").strip(),
        "square_access_token": _main_cfg.get("square_access_token", "").strip(),
        "square_location_id":  _main_cfg.get("square_location_id", "").strip(),
        "square_fallback_url": _main_cfg.get("square_payment_url", "").strip(),
        # Email links default ON — this preserves the exact behavior the
        # feature already had, unconditionally, before this toggle existed.
        "email_enabled": bool(_main_cfg.get("email_payment_link_enabled", True)),
        # SMS links default OFF — a new capability, and real SMS traffic
        # containing a link shouldn't go out until the toll-free
        # registration's sample message is updated to match (see the
        # compliance conversation this feature came out of).
        "sms_enabled": bool(_main_cfg.get("sms_payment_link_enabled", False)),
    }


def _create_stripe_checkout_url(secret_key: str, amount_dollars: float,
                                 description: str, invoice_id: str) -> "str | None":
    """
    Creates a fresh, single-use Stripe Checkout Session for exactly this
    invoice's amount and returns its URL, or None on any failure (network,
    bad key, etc. — callers fall back to a static URL when this returns
    None, never raise up to the caller).
    """
    try:
        import requests as _req_stripe
        _cents = int(round(amount_dollars * 100))
        resp = _req_stripe.post(
            "https://api.stripe.com/v1/checkout/sessions",
            auth=(secret_key, ""),
            data={
                "mode": "payment",
                "success_url": "https://ai-prowler.com/",
                "line_items[0][price_data][currency]": "usd",
                "line_items[0][price_data][product_data][name]": description or f"Invoice {invoice_id}",
                "line_items[0][price_data][unit_amount]": _cents,
                "line_items[0][quantity]": 1,
                "client_reference_id": invoice_id,
            },
            timeout=15,
        )
        if resp.status_code == 200:
            return resp.json().get("url")
        _log.warning("Stripe checkout session creation failed (%s): %s",
                     resp.status_code, resp.text[:300])
        return None
    except Exception as exc:
        _log.warning("Stripe checkout session creation error: %s", exc)
        return None


def _create_square_checkout_url(access_token: str, location_id: str,
                                 amount_dollars: float, description: str,
                                 invoice_id: str) -> "str | None":
    """
    Creates a fresh, single-use Square payment link for exactly this
    invoice's amount and returns its URL, or None on any failure. Same
    graceful-fallback contract as _create_stripe_checkout_url().
    """
    try:
        import requests as _req_sq, uuid as _uuid_sq
        _cents = int(round(amount_dollars * 100))
        resp = _req_sq.post(
            "https://connect.squareup.com/v2/online-checkout/payment-links",
            headers={
                "Authorization": f"Bearer {access_token}",
                "Content-Type": "application/json",
                "Square-Version": "2026-05-20",
            },
            json={
                "idempotency_key": str(_uuid_sq.uuid4()),
                "quick_pay": {
                    "name": description or f"Invoice {invoice_id}",
                    "price_money": {"amount": _cents, "currency": "USD"},
                    "location_id": location_id,
                },
            },
            timeout=15,
        )
        if resp.status_code == 200:
            return resp.json().get("payment_link", {}).get("url")
        _log.warning("Square payment link creation failed (%s): %s",
                     resp.status_code, resp.text[:300])
        return None
    except Exception as exc:
        _log.warning("Square payment link creation error: %s", exc)
        return None


def _find_invoice_row(invoice_identifier: str, filepath: str, ctx) -> dict:
    """
    Shared invoice-lookup + crew-scope-check logic used by email_invoice(),
    text_invoice(), email_receipt(), and text_receipt().

    2026-09-13: fully ported off openpyxl. This used to open the .xlsx Job
    Tracker directly and scan the Invoices/Jobs_Schedule/Customers sheets
    cell by cell — a path that stopped being live the moment create_invoice()
    (and every other write tool) moved to SQLite-only. Since then, these
    four tools could not reliably find ANY invoice created after the
    migration — a real, previously-undiscovered break in the whole
    invoice/receipt-sending pipeline, found while checking the newly-wired
    Database tab's Settings screen and tracing where Business Settings
    actually gets used.

    Returns a dict with either:
        {"error": "<message starting with ❌>"}          on failure
        {"inv_row": <dict>, "db_path": <str>}             on success

    inv_row's keys deliberately match the exact strings email_invoice()/
    text_invoice()/email_receipt()/text_receipt() already query via
    inv_row.get(...) — no changes needed in those four functions' own
    field-access code, only in how the row itself gets built and (for
    email_invoice/email_receipt) how the customer's email gets resolved.
    """
    db_path = _resolve_job_db_path(ctx, filepath)
    if not db_path:
        return {"error": "❌ No spreadsheet path configured. Set one in Settings → Small Business."}

    # Critical: an empty invoice_identifier must never silently match the
    # first row in the table — see this function's own history (the
    # openpyxl version's identical guard) for the real incident this
    # protects against: someone else's invoice going to the wrong customer.
    if not invoice_identifier or not invoice_identifier.strip():
        return {"error": "❌ invoice_identifier is required and cannot be blank."}

    import sqlite3 as _sqlite3_fir
    conn = _sqlite3_fir.connect(db_path)
    conn.row_factory = _sqlite3_fir.Row
    like = f"%{invoice_identifier.strip().lower()}%"
    row = conn.execute(
        "SELECT * FROM invoices WHERE LOWER(invoice_id) LIKE ? "
        "OR LOWER(customer_name) LIKE ? OR LOWER(job_id) LIKE ? "
        "ORDER BY rowid LIMIT 1",
        (like, like, like),
    ).fetchone()

    if row is None:
        conn.close()
        return {"error": f"❌ No invoice found matching '{invoice_identifier}'."}

    # ── Server-mode crew scoping (Phase 4) ──────────────────────────────────
    # The invoices table itself has no crew column of its own — cross-
    # reference the invoice's job_id against jobs.crew instead (the source
    # of truth), same pattern log_time_entry/update_job_spreadsheet use.
    # A restricted user accessing an invoice for a job that isn't theirs
    # is rejected before anything is sent, not silently allowed.
    restrict, crew_name = _job_crew_scope(ctx, db_path)
    if restrict:
        job_id = str(row["job_id"] or "")
        row_crew = ""
        if job_id:
            jrow = conn.execute("SELECT crew FROM jobs WHERE job_id = ?", (job_id,)).fetchone()
            if jrow:
                row_crew = str(jrow["crew"] or "").strip().lower()
        if not _crew_name_in_cell(row_crew, crew_name):
            conn.close()
            return {"error": (
                "❌ You can only access invoices for jobs assigned to you "
                "(Crew / Technician column). This invoice's job is not assigned to you."
            )}

    inv_row = {
        "InvoiceID (INV-####)":     row["invoice_id"],
        "JobID (JOB-####)":         row["job_id"],
        "CustomerID":               row["customer_id"],
        "Customer Name / Company":  row["customer_name"],
        "Invoice Date":             row["invoice_date"],
        "Due Date (Net 30)":        row["due_date"],
        "Service Date":             row["service_date"],
        "Service Type":             row["service_type"],
        "Description":              row["description"],
        "Subtotal ($)":             row["subtotal"],
        "Discount ($)":             row["discount"],
        "Tax 7% ($)":               row["tax"],
        "TOTAL DUE ($)":            row["total_due"],
        "Balance Due ($)":          row["balance_due"],
        "Payment Status":           row["payment_status"],
    }
    conn.close()
    return {"inv_row": inv_row, "db_path": db_path}


def _lookup_invoice_customer_email(db_path: str, cust_id: str, cust_name: str) -> str:
    """DB-backed customer-email lookup for email_invoice()/email_receipt()
    when no `to` address is given. Replaces a hand-rolled scan of the
    Customers worksheet with the same two-tier matching the old code used:
    exact CustomerID match first, falling back to a company/first-name
    substring match. Returns "" (never raises) if nothing matches, so
    callers can fall through to their own "no recipient" error message.

    Deliberately NOT named _lookup_customer_email — that name is already
    taken by an older, single-argument helper used by send_email()/
    send_alert() (name_or_id: str). That older helper is STILL fully
    openpyxl-based itself (same class of bug this whole fix addresses,
    found while porting this one) — a separate, real gap in a different
    pair of tools than the four (email_invoice/text_invoice/email_
    receipt/text_receipt) this pass was scoped to. Flagged, not fixed
    here, to avoid scope creep into tools that weren't part of this ask.
    """
    import sqlite3 as _sqlite3_cel
    conn = _sqlite3_cel.connect(db_path)
    conn.row_factory = _sqlite3_cel.Row
    try:
        if cust_id:
            row = conn.execute(
                "SELECT email FROM customers WHERE customer_id = ?", (cust_id,)
            ).fetchone()
            if row and row["email"]:
                return str(row["email"])
        if cust_name:
            like = f"%{cust_name.strip().lower()}%"
            row = conn.execute(
                "SELECT email FROM customers WHERE LOWER(company_name) LIKE ? "
                "OR LOWER(first_name) LIKE ? LIMIT 1",
                (like, like),
            ).fetchone()
            if row and row["email"]:
                return str(row["email"])
    finally:
        conn.close()
    return ""


@mcp.tool()
def email_invoice(
    invoice_identifier: str,
    to:                 str  = "",
    filepath:           str  = "",
    also_sms:           bool = False,
    ctx:                "Context | None" = None,
) -> str:
    """
    Email a professional HTML invoice to a customer directly from the spreadsheet.

    Reads the matching invoice row from the Invoices sheet, formats it as a
    clean HTML email, and sends it via the configured SMTP account.

    Args:
        invoice_identifier: InvoiceID (e.g. "INV-0001") or customer name
                            (partial match accepted, e.g. "Torres").
        to:                 Recipient email address. If omitted, looks up the
                            customer email in the Customers sheet automatically.
        filepath:           Path to the SQLite job database. Uses the default
                            path from Settings if omitted.
        also_sms:           If True, also send an SMS notification to the
                            customer after the email succeeds. The SMS reuses
                            the same payment-link checkout session (one session
                            created, shared by both channels). The SMS payment
                            link is included only when sms_payment_link_enabled
                            is on in Settings → Small Business. An SMS failure
                            does not turn a successful email into an error.
        ctx:                MCP context (injected automatically).

    Returns:
        Confirmation with invoice total and recipient, or an error message.

    Voice examples:
        "Email the invoice for INV-0001 to the customer"
        "Send Karen's invoice"
        "Email the Blue Wave Cafe invoice"
    """
    _telemetry_increment_tool_count("email_invoice")

    _ei_lookup = _find_invoice_row(invoice_identifier, filepath, ctx)
    if "error" in _ei_lookup:
        return _ei_lookup["error"]
    inv_row = _ei_lookup["inv_row"]
    db_path = _ei_lookup["db_path"]

    # ── Look up customer email if not provided ────────────────────────────────
    if not to:
        cust_id = str(inv_row.get("CustomerID", "") or "")
        cust_name = str(inv_row.get("Customer Name / Company", "") or "")
        to = _lookup_invoice_customer_email(db_path, cust_id, cust_name)
        if not to:
            return (f"❌ No recipient email provided and could not auto-find customer email.\n"
                    f"Pass a 'to' address: email_invoice('{invoice_identifier}', to='email@example.com')")

    # ── Build HTML invoice ────────────────────────────────────────────────────
    import datetime as _dt

    def _fv(key, default="—"):
        v = inv_row.get(key)
        if v is None or str(v).strip() == "":
            return default
        if isinstance(v, _dt.datetime):
            return v.strftime("%B %d, %Y")
        if isinstance(v, _dt.date):
            return v.strftime("%B %d, %Y")
        return str(v).strip()

    def _fmt_money(key):
        v = inv_row.get(key)
        try:
            return f"${float(v):,.2f}"
        except (TypeError, ValueError):
            return "—"

    inv_id    = _fv("InvoiceID (INV-####)")
    job_id    = _fv("JobID (JOB-####)")
    cust      = _fv("Customer Name / Company")
    inv_date  = _fv("Invoice Date")
    due_date  = _fv("Due Date (Net 30)")
    svc_date  = _fv("Service Date")
    svc_type  = _fv("Service Type")
    desc      = _fv("Description")
    subtotal  = _fmt_money("Subtotal ($)")
    discount  = _fmt_money("Discount ($)")
    tax       = _fmt_money("Tax 7% ($)")
    total_due = _fmt_money("TOTAL DUE ($)")
    balance   = _fmt_money("Balance Due ($)")
    pmt_status= _fv("Payment Status", "Unpaid")

    # Business identity — Settings sheet's own Notes column says these
    # rows "Appear on invoices and email headers" / "Printed on invoices",
    # but nothing previously read them, so every invoice looked like it
    # came from "AI-Prowler" with no indication of which business the
    # customer is actually paying.
    _biz = _read_business_info(db_path)
    _biz_name    = _biz["name"] or "Your Business"
    _biz_lines   = []
    if _biz["address"]:
        _biz_lines.append(_biz["address"])
    if _biz["phone"]:
        _biz_lines.append(_biz["phone"])
    if _biz["email"]:
        _biz_lines.append(_biz["email"])
    if _biz["website"]:
        _biz_lines.append(_biz["website"])
    _biz_subline = " &nbsp;|&nbsp; ".join(_biz_lines)
    _biz_license = (f'<p style="margin:2px 0 0;font-size:11px;opacity:0.7;">'
                    f'License/LLC: {_biz["license"]}</p>'
                    if _biz["license"] else "")

    html_body = f"""<!DOCTYPE html>
<html>
<head><meta charset="UTF-8">
<style>
  body {{ font-family: Arial, sans-serif; color: #333; max-width: 650px; margin: 0 auto; }}
  .header {{ background: #1a3c5e; color: white; padding: 24px 32px; }}
  .header h1 {{ margin: 0; font-size: 28px; letter-spacing: 1px; }}
  .header .biz-name {{ margin: 0 0 6px; font-size: 16px; font-weight: bold; }}
  .header p  {{ margin: 4px 0 0; font-size: 13px; opacity: 0.85; }}
  .section   {{ padding: 14px 32px; }}
  .row-table {{ width: 100%; border-collapse: collapse; }}
  .label     {{ color: #666; font-size: 14px; text-align: left; padding: 4px 0; }}
  .value     {{ font-weight: 600; font-size: 14px; text-align: right; padding: 4px 0; }}
  table      {{ width: 100%; border-collapse: collapse; margin-top: 8px; }}
  th         {{ background: #f0f4f8; text-align: left; padding: 10px; font-size: 13px; color: #555; }}
  td         {{ padding: 10px; border-bottom: 1px solid #eee; font-size: 14px; }}
  .totals    {{ background: #f9f9f9; padding: 12px 32px; }}
  .total-td  {{ padding: 3px 0; font-size: 14px; }}
  .total-label {{ text-align: left; }}
  .total-value {{ text-align: right; }}
  .grand     {{ font-size: 18px; font-weight: bold; color: #1a3c5e; border-top: 2px solid #1a3c5e; margin-top: 8px; padding-top: 8px; }}
  .footer    {{ background: #f0f4f8; padding: 16px 32px; font-size: 12px; color: #888; }}
  .badge     {{ display: inline-block; padding: 4px 10px; border-radius: 12px; font-size: 12px; font-weight: bold;
                background: {'#e8f5e9' if pmt_status == 'Paid' else '#fff3e0'}; 
                color: {'#2e7d32' if pmt_status == 'Paid' else '#e65100'}; }}
</style>
</head>
<body>
<div class="header">
  <p class="biz-name">{_biz_name}</p>
  <h1>INVOICE</h1>
  <p>{inv_id} &nbsp;|&nbsp; {job_id}</p>
  {f'<p>{_biz_subline}</p>' if _biz_subline else ''}
  {_biz_license}
</div>
<div class="section">
  <table class="row-table" cellpadding="0" cellspacing="0">
    <tr><td class="label">Bill To</td><td class="value">{cust}</td></tr>
    <tr><td class="label">Service Date</td><td class="value">{svc_date}</td></tr>
    <tr><td class="label">Invoice Date</td><td class="value">{inv_date}</td></tr>
    <tr><td class="label">Due Date</td><td class="value">{due_date}</td></tr>
    <tr><td class="label">Status</td><td class="value"><span class="badge">{pmt_status}</span></td></tr>
  </table>
</div>
<div class="section">
  <table>
    <tr><th>Service</th><th>Description</th><th>Amount</th></tr>
    <tr><td>{svc_type}</td><td>{desc}</td><td>{subtotal}</td></tr>
  </table>
</div>
<div class="totals">
  <table class="row-table" cellpadding="0" cellspacing="0">
    <tr><td class="total-td total-label">Subtotal</td><td class="total-td total-value">{subtotal}</td></tr>
    <tr><td class="total-td total-label">Discount</td><td class="total-td total-value">({discount})</td></tr>
    <tr><td class="total-td total-label">Tax (7%)</td><td class="total-td total-value">{tax}</td></tr>
    <tr class="grand"><td class="total-td total-label">TOTAL DUE</td><td class="total-td total-value">{total_due}</td></tr>
    {"" if pmt_status == "Paid" else f'<tr><td class="total-td total-label" style="color:#e65100">Balance Due</td><td class="total-td total-value" style="color:#e65100">{balance}</td></tr>'}
  </table>
</div>
<div class="footer">
  <p>Thank you for your business! Questions? Reply to this email.</p>
  <p>Please make payment by <strong>{due_date}</strong>.</p>
</div>
</body>
</html>"""

    # ── Payment links: dynamic (correct amount, per-invoice) preferred,
    #    static fallback if no credentials are configured. Email-only —
    #    text_invoice() computes its own links separately, gated by
    #    sms_payment_link_enabled instead of email_payment_link_enabled,
    #    since the two channels are sent independently now (never both
    #    for the same invoice, by design). ──────────────────────────
    _pay = _load_payment_settings()
    try:
        _raw_total = float(inv_row.get("TOTAL DUE ($)"))
    except (TypeError, ValueError):
        _raw_total = None
    _pay_desc = f"Invoice {inv_id} — {job_id}"
    _need_links = _pay["email_enabled"]

    _stripe_url = None
    _square_url = None
    if _need_links:
        if _pay["stripe_secret_key"] and _raw_total is not None:
            _stripe_url = _create_stripe_checkout_url(
                _pay["stripe_secret_key"], _raw_total, _pay_desc, inv_id)
        if not _stripe_url and _pay["stripe_fallback_url"]:
            _stripe_url = _pay["stripe_fallback_url"]

        if _pay["square_access_token"] and _pay["square_location_id"] and _raw_total is not None:
            _square_url = _create_square_checkout_url(
                _pay["square_access_token"], _pay["square_location_id"],
                _raw_total, _pay_desc, inv_id)
        if not _square_url and _pay["square_fallback_url"]:
            _square_url = _pay["square_fallback_url"]

    _active_links = []  # list of (name, url, color) — email section only
    if _pay["email_enabled"]:
        if _stripe_url:
            _active_links.append(("Stripe", _stripe_url, "#635BFF"))
        if _square_url:
            _active_links.append(("Square", _square_url, "#00B388"))

    if _active_links:
        _btn_html = "".join(
            f'<a href="{url}" style="display:inline-block;margin:0 8px 8px 0;'
            f'padding:12px 24px;background:{color};color:white;text-decoration:none;'
            f'border-radius:6px;font-family:Arial,sans-serif;font-size:14px;'
            f'font-weight:bold;">Pay with {name}</a>'
            for name, url, color in _active_links
        )
        _pay_section = (
            '<div style="padding:20px 32px;background:#f8f9ff;border-top:1px solid #e0e0e0;">'
            '<p style="margin:0 0 12px;font-family:Arial,sans-serif;font-size:15px;'
            'font-weight:bold;color:#1a3c5e;">Pay Online</p>'
            f'{_btn_html}'
            '<p style="margin:12px 0 0;font-family:Arial,sans-serif;font-size:11px;'
            'color:#999;">Click a button above to pay securely online.</p></div>'
        )
        # Insert pay section before </body>
        html_body = html_body.replace("</body>", _pay_section + "</body>")


    subject = f"Invoice {inv_id} — {cust} — {total_due}"

    # ── Send via the shared, backend-aware _send_smtp() router ────────────────
    # This was previously a separate, hardcoded raw-SMTP-only implementation
    # that never consulted the configured backend (Outlook / SMTP /
    # Outlook+SMTP) — it always tried plain SMTP regardless of Settings,
    # so a user with Outlook configured (no password needed) would still
    # get an SMTP authentication failure if their SMTP app password was
    # blank, stale, or never set. _send_smtp() is the same function
    # send_email()/email_receipt() already use — it correctly tries Outlook
    # first when configured, only falling back to SMTP if Outlook fails or
    # isn't set up, exactly matching what the Settings panel's backend
    # checkboxes promise ("No password needed for Outlook").
    cfg = _email_config_load()
    if not cfg:
        return ("❌ Email not configured. Call configure_email() first.")

    to = (to or "").strip()
    if not to:
        return "❌ Could not determine recipient email address."

    _plain_body = (
        f"Invoice {inv_id} for {cust}\n"
        f"Service: {svc_type}\n"
        f"Total Due: {total_due}\n"
        f"Due Date: {due_date}\n\n"
        f"View this invoice in HTML format if your email client supports it."
    )

    try:
        _ei_ok, _ei_msg = _send_smtp(
            to, subject, _plain_body, body_html=html_body)
    except Exception as exc:
        return f"❌ Email send failed: {exc}"

    if not _ei_ok:
        return f"❌ Email send failed: {_ei_msg}"

    _email_result_msg = (
        f"✅ Invoice emailed\n"
        f"   Invoice:   {inv_id}  ({job_id})\n"
        f"   Customer:  {cust}\n"
        f"   Total Due: {total_due}\n"
        f"   Sent to:   {to}\n"
        f"   Subject:   {subject}"
    )

    # ── also_sms: companion SMS notification (optional) ───────────────────────
    # Reuses the checkout URL(s) already built above — one session, two channels.
    # Gated by sms_payment_link_enabled independently of the email toggle.
    # A failure here must NOT turn a successful email into an error response.
    if also_sms:
        _sms_cust = str(inv_row.get("Customer Name / Company", "") or "").strip()
        if not _sms_cust:
            _email_result_msg += "\n   SMS:       not sent (customer name blank on invoice)"
        else:
            # Build the SMS pay link (reuse whichever URL was created above)
            _sms_pay_link = ""
            if _pay.get("sms_enabled"):
                _sms_pay_link = _stripe_url or _square_url or ""
            _sms_msg = (
                f"Hi {_sms_cust}, your invoice {inv_id} for {total_due} has been emailed."
                + (f" Pay online: {_sms_pay_link}" if _sms_pay_link else "")
            )
            try:
                _sms_result = send_sms(to=_sms_cust, message=_sms_msg, ctx=ctx)
                if _sms_result.startswith("❌"):
                    _email_result_msg += f"\n   SMS:       not sent ({_sms_result})"
                else:
                    _email_result_msg += f"\n   SMS:       sent to {_sms_cust}"
            except Exception as _sms_exc:
                _email_result_msg += f"\n   SMS:       not sent ({_sms_exc})"

    return _email_result_msg


@mcp.tool()
def text_invoice(
    invoice_identifier: str,
    filepath:           str = "",
    ctx:                "Context | None" = None,
) -> str:
    """
    Send an SMS notification for an invoice — text only, no email sent
    alongside it. The companion to email_invoice(): use this when the
    customer should be billed through exactly one channel, not both at
    once (email_invoice() and text_invoice() are mutually exclusive by
    design for that reason).

    SMS can't carry the actual formatted invoice document — there's no
    way to attach a file to a text — so this sends a short notification
    with the amount due, plus a payment link if sms_payment_link_enabled
    is turned on in Settings → Small Business (default off, since real
    SMS traffic with a link shouldn't go out until the toll-free
    registration's sample message is updated to include one).

    Args:
        invoice_identifier: InvoiceID (e.g. "INV-0001") or customer name
                            (partial match accepted, e.g. "Torres").
        filepath:           Path to the SQLite job database. Uses the default
                            path from Settings if omitted.
        ctx:                MCP context (injected automatically).

    Returns:
        Confirmation with invoice total and recipient, or an error message.

    Voice examples:
        "Text the invoice for INV-0001 to the customer"
        "Text Karen her invoice"
        "Text — not email — the Blue Wave Cafe invoice"
    """
    _telemetry_increment_tool_count("text_invoice")

    _ti_lookup = _find_invoice_row(invoice_identifier, filepath, ctx)
    if "error" in _ti_lookup:
        return _ti_lookup["error"]
    inv_row = _ti_lookup["inv_row"]

    def _ti_fmt_money(key):
        v = inv_row.get(key)
        try:
            return f"${float(v):,.2f}"
        except (TypeError, ValueError):
            return "—"

    job_id = str(inv_row.get("JobID (JOB-####)", "") or "").strip() or "—"
    inv_id = str(inv_row.get("InvoiceID (INV-####)", "") or "").strip() or "—"
    total_due = _ti_fmt_money("TOTAL DUE ($)")

    # The invoice row's customer name field, used both as the SMS
    # recipient lookup key and the greeting — must be the RAW value, not
    # a "—" display placeholder. See email_invoice()'s history for why
    # that distinction matters: a placeholder character fed into
    # send_sms()'s name-search is a latent bug waiting to coincidentally
    # match unrelated data rather than a real customer.
    cust_name = str(inv_row.get("Customer Name / Company", "") or "").strip()
    if not cust_name:
        return "❌ This invoice has no customer name on file — can't determine who to text."

    try:
        _ti_raw_total = float(inv_row.get("TOTAL DUE ($)"))
    except (TypeError, ValueError):
        _ti_raw_total = None

    _ti_pay = _load_payment_settings()
    _ti_link = None
    if _ti_pay["sms_enabled"] and _ti_raw_total is not None:
        _ti_desc = f"Invoice {inv_id} — {job_id}"
        if _ti_pay["stripe_secret_key"]:
            _ti_link = _create_stripe_checkout_url(
                _ti_pay["stripe_secret_key"], _ti_raw_total, _ti_desc, inv_id)
        if not _ti_link and _ti_pay["stripe_fallback_url"]:
            _ti_link = _ti_pay["stripe_fallback_url"]
        if not _ti_link and _ti_pay["square_access_token"] and _ti_pay["square_location_id"]:
            _ti_link = _create_square_checkout_url(
                _ti_pay["square_access_token"], _ti_pay["square_location_id"],
                _ti_raw_total, _ti_desc, inv_id)
        if not _ti_link and _ti_pay["square_fallback_url"]:
            _ti_link = _ti_pay["square_fallback_url"]

    if _ti_link:
        _ti_msg = (
            f"Hi {cust_name}, your invoice for {job_id} is ready — total due: "
            f"{total_due}. Pay now: {_ti_link}"
        )
    else:
        _ti_msg = (
            f"Hi {cust_name}, your invoice for {job_id} is ready — total due: "
            f"{total_due}. Reply here with any questions."
        )

    _ti_result = send_sms(to=cust_name, message=_ti_msg, ctx=ctx)
    if _ti_result.startswith("❌"):
        return _ti_result
    return (
        f"✅ Invoice texted\n"
        f"   Invoice:   {inv_id}  ({job_id})\n"
        f"   Customer:  {cust_name}\n"
        f"   Total Due: {total_due}"
    )


# ══════════════════════════════════════════════════════════════════════════════
# ACTION TOOL 8b — email_receipt  +  text_receipt
#
# Companion to email_invoice / text_invoice for jobs paid by cash, check, or
# other offline means. Sends a "Payment Received — Thank You" confirmation
# rather than a bill. Uses the same _find_invoice_row lookup + customer
# email/phone resolution as the invoice tools.
# ══════════════════════════════════════════════════════════════════════════════


@mcp.tool()
def email_receipt(
    invoice_identifier: str,
    payment_method:     str  = "Cash",
    to:                 str  = "",
    filepath:           str  = "",
    ctx:                "Context | None" = None,
) -> str:
    """
    Email a payment-received receipt to a customer after they pay by cash,
    check, or other offline method. Sends a clean HTML confirmation email —
    NOT an invoice (use email_invoice for that). Intended for jobs where
    the Payment field is "Cash", "Check", or similar and no billing link is
    needed, just a thank-you / proof-of-payment.

    Uses the same invoice-row lookup and customer-email resolution as
    email_invoice(), so the same invoice_identifier values work.

    Args:
        invoice_identifier: InvoiceID (e.g. "INV-0001") or customer name.
        payment_method:     How they paid — "Cash", "Check", "Zelle", etc.
                            Shown in the receipt body. Defaults to "Cash".
        to:                 Recipient email. Auto-resolved from Customers
                            sheet if omitted.
        filepath:           Path to the SQLite job database. Uses default if
                            omitted.
        ctx:                MCP context (injected automatically).

    Returns:
        Confirmation with receipt details, or an error message.
    """
    _telemetry_increment_tool_count("email_receipt")

    _er_lookup = _find_invoice_row(invoice_identifier, filepath, ctx)
    if "error" in _er_lookup:
        return _er_lookup["error"]
    inv_row = _er_lookup["inv_row"]
    db_path = _er_lookup["db_path"]

    # ── Resolve recipient email ────────────────────────────────────────────────
    if not to:
        cust_id   = str(inv_row.get("CustomerID", "") or "")
        cust_name = str(inv_row.get("Customer Name / Company", "") or "")
        to = _lookup_invoice_customer_email(db_path, cust_id, cust_name)
        if not to:
            return (f"❌ No recipient email and could not auto-find customer email.\n"
                    f"Pass a 'to' address: email_receipt('{invoice_identifier}', to='email@example.com')")

    # ── Field helpers ──────────────────────────────────────────────────────────
    import datetime as _dt

    def _rv(key, default="—"):
        v = inv_row.get(key)
        if v is None or str(v).strip() == "":
            return default
        if isinstance(v, _dt.datetime):
            return v.strftime("%B %d, %Y")
        if isinstance(v, _dt.date):
            return v.strftime("%B %d, %Y")
        return str(v).strip()

    def _rfmt(key):
        v = inv_row.get(key)
        try:    return f"${float(v):,.2f}"
        except: return "—"

    inv_id    = _rv("InvoiceID (INV-####)")
    job_id    = _rv("JobID (JOB-####)")
    cust      = _rv("Customer Name / Company")
    svc_date  = _rv("Service Date")
    svc_type  = _rv("Service Type")
    desc      = _rv("Description")
    subtotal  = _rfmt("Subtotal ($)")
    tax       = _rfmt("Tax 7% ($)")
    total_due = _rfmt("TOTAL DUE ($)")
    address   = _rv("Service Address")
    paid_date = _dt.date.today().strftime("%B %d, %Y")
    pm        = (payment_method or "Cash").strip()

    # Business identity — same rationale as email_invoice()'s identical fix.
    _biz = _read_business_info(db_path)
    _biz_name = _biz["name"] or "Your Business"
    _biz_lines = [v for v in (_biz["address"], _biz["phone"], _biz["email"])
                  if v]
    _biz_subline = " &nbsp;|&nbsp; ".join(_biz_lines)

    # ── Build HTML receipt ─────────────────────────────────────────────────────
    html_body = f"""<!DOCTYPE html>
<html><head><meta charset="UTF-8">
<title>Payment Receipt — {inv_id}</title>
<style>
  /* Same proven row-table pattern used by email_invoice() — the user
     specifically confirmed this spacing looks right in Outlook, unlike
     the receipt's earlier per-row-border/inline-style approach. No
     border-bottom on individual rows here; just clean class-based
     padding, matching invoice's Bill To section exactly. */
  .row-table {{ width: 100%; border-collapse: collapse; }}
  .label     {{ color: #666; font-size: 14px; text-align: left; padding: 4px 0; }}
  .value     {{ font-weight: 600; font-size: 14px; text-align: right; padding: 4px 0; }}
  .total-td  {{ padding: 3px 0; font-size: 14px; }}
  .total-label {{ text-align: left; color: #666; }}
  .total-value {{ text-align: right; font-weight: 600; }}
  .grand     {{ font-size: 16px; font-weight: bold; color: #2e7d32; border-top: 2px solid #2e7d32; padding-top: 6px; }}
</style>
</head>
<body style="margin:0;padding:0;background:#f5f5f5;font-family:Arial,sans-serif;">
<table width="100%" cellpadding="0" cellspacing="0" style="background:#f5f5f5;padding:32px 0;">
<tr><td align="center">
<table width="600" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:8px;
  box-shadow:0 2px 8px rgba(0,0,0,.12);overflow:hidden;max-width:600px;">

  <tr><td style="background:#1a3c5e;padding:28px 32px;">
    <p style="margin:0 0 8px;color:#ffffff;font-size:15px;font-weight:bold;">{_biz_name}</p>
    <h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">
      ✅ Payment Received — Thank You!
    </h1>
    <p style="margin:6px 0 0;color:#a8c4d8;font-size:13px;">Receipt #{inv_id}</p>
    {f'<p style="margin:4px 0 0;color:#a8c4d8;font-size:12px;">{_biz_subline}</p>' if _biz_subline else ''}
  </td></tr>

  <tr><td style="padding:28px 32px;">
    <p style="margin:0 0 20px;font-size:15px;color:#333;">
      Dear <strong>{cust}</strong>,<br><br>
      Thank you for your payment! This email confirms that we have received your
      payment in full. Please keep this receipt for your records.
    </p>

    <table class="row-table" cellpadding="0" cellspacing="0">
      <tr><td class="label">Receipt #</td><td class="value">{inv_id}</td></tr>
      <tr><td class="label">Job #</td><td class="value">{job_id}</td></tr>
      <tr><td class="label">Date Paid</td><td class="value">{paid_date}</td></tr>
      <tr><td class="label">Payment Method</td><td class="value">{pm}</td></tr>
      <tr><td class="label">Service Date</td><td class="value">{svc_date}</td></tr>
      <tr><td class="label">Service</td><td class="value">{svc_type}</td></tr>
      <tr><td class="label">Description</td><td class="value">{desc}</td></tr>
      {'<tr><td class="label">Address</td><td class="value">' + address + '</td></tr>' if address != '—' else ''}
    </table>

    <table class="row-table" cellpadding="0" cellspacing="0" style="margin-top:16px;">
      <tr><td class="total-td total-label">Subtotal</td><td class="total-td total-value">{subtotal}</td></tr>
      <tr><td class="total-td total-label">Tax (7%)</td><td class="total-td total-value">{tax}</td></tr>
      <tr class="grand"><td class="total-td total-label">AMOUNT PAID</td><td class="total-td total-value">{total_due}</td></tr>
    </table>

    <p style="margin:0;font-size:13px;color:#888;text-align:center;">
      Thank you for your business! We appreciate your trust and look forward
      to serving you again.
    </p>
  </td></tr>

</table>
</td></tr></table>
</body></html>"""

    subject = f"Payment Receipt #{inv_id} — {cust} — {total_due} — Thank You!"

    cfg = _email_config_load()
    if not cfg:
        return "❌ Email not configured. Call configure_email() first."

    # Send via the shared, backend-aware _send_smtp() router — see the
    # identical fix and rationale in email_invoice() just above. This was
    # previously a hardcoded raw-SMTP-only send that ignored the configured
    # backend entirely, so an Outlook-configured user (no password needed)
    # would still fail here on a blank/stale SMTP app password.
    _to = to.strip()
    _plain_body = (
        f"Payment Receipt #{inv_id} for {cust}\n"
        f"Amount Paid: {total_due}\n"
        f"Payment Method: {pm}\n\n"
        f"Thank you for your business!"
    )

    try:
        _er_ok, _er_msg = _send_smtp(
            _to, subject, _plain_body, body_html=html_body)
    except Exception as exc:
        return f"❌ Email send failed: {exc}"

    if not _er_ok:
        return f"❌ Email send failed: {_er_msg}"

    return (
        f"✅ Receipt emailed\n"
        f"   Invoice:   {inv_id}  ({job_id})\n"
        f"   Customer:  {cust}\n"
        f"   Amount:    {total_due}\n"
        f"   Method:    {pm}\n"
        f"   Sent to:   {_to}"
    )


@mcp.tool()
def text_receipt(
    invoice_identifier: str,
    payment_method:     str  = "Cash",
    filepath:           str  = "",
    ctx:                "Context | None" = None,
) -> str:
    """
    Text an SMS payment-received receipt to a customer after they pay by
    cash, check, or other offline method. Companion to email_receipt() —
    use this when the customer should get a text confirmation instead of
    (or in addition to) an email. NOT a bill — for invoicing use text_invoice().

    Args:
        invoice_identifier: InvoiceID (e.g. "INV-0001") or customer name.
        payment_method:     How they paid — "Cash", "Check", "Zelle", etc.
                            Defaults to "Cash".
        filepath:           Path to the SQLite job database. Uses default if omitted.
        ctx:                MCP context (injected automatically).

    Returns:
        Confirmation with receipt details, or an error message.
    """
    _telemetry_increment_tool_count("text_receipt")

    _tr_lookup = _find_invoice_row(invoice_identifier, filepath, ctx)
    if "error" in _tr_lookup:
        return _tr_lookup["error"]
    inv_row = _tr_lookup["inv_row"]

    def _tr_fmt(key):
        v = inv_row.get(key)
        try:    return f"${float(v):,.2f}"
        except: return "—"

    inv_id    = str(inv_row.get("InvoiceID (INV-####)", "") or "").strip() or "—"
    job_id    = str(inv_row.get("JobID (JOB-####)", "") or "").strip() or "—"
    total_amt = _tr_fmt("TOTAL DUE ($)")
    cust_name = str(inv_row.get("Customer Name / Company", "") or "").strip()
    pm        = (payment_method or "Cash").strip()

    if not cust_name:
        return "❌ This invoice has no customer name on file — can't determine who to text."

    _tr_msg = (
        f"Hi {cust_name}, thank you! We received your {pm} payment of {total_amt} "
        f"for job {job_id}. Receipt #{inv_id}. We appreciate your business!"
    )

    _tr_result = send_sms(to=cust_name, message=_tr_msg, ctx=ctx)
    if _tr_result.startswith("❌"):
        return _tr_result
    return (
        f"✅ Receipt texted\n"
        f"   Invoice:   {inv_id}  ({job_id})\n"
        f"   Customer:  {cust_name}\n"
        f"   Amount:    {total_amt}\n"
        f"   Method:    {pm}"
    )


# ══════════════════════════════════════════════════════════════════════════════
# ACTION TOOL 9 — save_contact  +  send_sms
#
# SMS is sent via Twilio (paid) — see send_sms() below.
#
# NOTE (v8.0.1): the free email-to-SMS carrier-gateway approach (sending
# email to <number>@vtext.com, txt.att.net, etc.) was removed. Carriers are
# shutting these gateways down industry-wide: AT&T's gateway is already
# gone (June 2025), T-Mobile's went offline December 2024, and Verizon's
# is mid-shutdown through March 2027. The remaining gateways are also
# unreliable while active — aggressive spam filtering on the sending side,
# no delivery confirmation, and no two-way reply support. Twilio (paid)
# replaces it entirely; see check_sms_replies() for inbound reply checking.
# ══════════════════════════════════════════════════════════════════════════════


@mcp.tool()
def save_contact(
    name:    str,
    phone:   str = "",
    email:   str = "",
    ctx:     "Context | None" = None,
) -> str:
    """
    Save or update a personal contact (phone and/or email) so future
    send_sms / send_email calls can use their name directly — e.g.
    "text David" or "email Vicki" — instead of repeating the number or
    address every time.

    This is for personal contacts (you, family, crew you message by name),
    not for customers — customers belong in the Customers spreadsheet sheet,
    which is checked automatically by send_sms/send_email and takes priority.

    Call this automatically (no need to ask first) whenever the operator
    tells you a name + phone number or name + email for the first time, e.g.
    "David's number is 386-555-0101" or "Vicki's email is vicki@gmail.com".

    Args:
        name:    Contact's name (e.g. "David", "Vicki"). Case-insensitive,
                 used as the lookup key — saving the same name again merges
                 with the existing record instead of overwriting it.
        phone:   Phone number, any format (digits are normalised).
        email:   Email address.
        ctx:     MCP context (injected automatically).

    Returns:
        Confirmation of what was saved.

    Voice examples:
        "David's number is 386-555-0101"
        "Save Vicki's email as vicki@gmail.com"
        "Remember that Jake's phone is 555-0199 and his email is jake@x.com"
    """
    _telemetry_increment_tool_count("save_contact")

    if not name.strip():
        return "❌ A contact name is required."
    if not phone.strip() and not email.strip():
        return "❌ Provide at least a phone number or an email address."

    _sc_user = _current_user(ctx)
    rec = _contact_save(name, phone=phone, email=email, user=_sc_user)

    # Report the ACTUAL filename the record was saved to — reuse
    # _CONTACTS_CACHE_PATH() itself rather than recomputing the filename
    # with separate (and previously mismatched) logic, which could show a
    # different, unsanitised filename than where the data really landed.
    cache_file = _CONTACTS_CACHE_PATH(_sc_user).name

    lines = [f"✅ Contact saved: {name.strip()}"]
    if rec.get('phone'):
        lines.append(f"   Phone:   {rec['phone']}")
    if rec.get('email'):
        lines.append(f"   Email:   {rec['email']}")
    lines.append(f"   (saved to {cache_file})")
    return '\n'.join(lines)


@mcp.tool()
def check_sms_configured(ctx: "Context | None" = None) -> str:
    """
    Lightweight check for whether an SMS provider (Twilio, SignalWire, or
    Vonage) is configured and valid. Reuses the exact same validation
    logic check_tools_status() already uses for its own SMS section, in
    a small dedicated tool rather than requiring a caller to parse that
    tool's larger free-text report just to answer one yes/no question.

    Primary use: the Jobs PWA calls this once to decide whether to
    enable or dim SMS-dependent buttons (like "Email + Text Invoice")
    BEFORE the user taps them, rather than letting them tap a button
    that's guaranteed to fail because nothing's configured yet.

    Returns:
        Exactly one of two strings, safe for exact-match parsing:
        "✅ SMS configured" or "❌ SMS not configured".
    """
    try:
        from sms_backends import get_sms_backend, load_sms_config
        _cfg = load_sms_config()
        _backend = get_sms_backend(_cfg)
        _ok, _ = _backend.validate_config()
    except Exception:
        _ok = False
    return "✅ SMS configured" if _ok else "❌ SMS not configured"


@mcp.tool()
def check_email_configured(ctx: "Context | None" = None) -> str:
    """
    Lightweight check for whether SMTP email is configured and has a host set.
    Mirrors check_sms_configured() — used by the Jobs PWA to decide whether
    to enable or dim the 'Email Invoice' button before the user taps it.

    Returns:
        Exactly one of two strings, safe for exact-match parsing:
        "✅ Email configured" or "❌ Email not configured".
    """
    try:
        cfg = _email_config_load()
        _ok = bool(cfg and cfg.get("smtp_host"))
    except Exception:
        _ok = False
    return "✅ Email configured" if _ok else "❌ Email not configured"


@mcp.tool()
def send_sms(
    to:      str,
    message: str,
    ctx:     "Context | None" = None,
) -> str:
    """
    Send an SMS text message to a crew member, customer, or saved contact.

    Requires an SMS provider to be configured in Settings → SMS / Text
    Messaging — Twilio, SignalWire, or Vonage (set via sms_provider). The
    free email-to-SMS carrier-gateway approach (vtext.com, txt.att.net,
    etc.) was removed — those gateways are being shut down industry-wide
    (AT&T's is already gone, Verizon's is mid-shutdown through 2027) and
    were unreliable even while active (spam filtering, no delivery
    confirmation, no two-way replies).

    'to' accepts a phone number OR a saved contact name (e.g. "David") —
    if it doesn't look like a number, contacts_cache.json is checked first,
    along with the Customers sheet and users.json by name.

    Server mode: any role (owner, manager, staff, field_crew) may send SMS
    here, via the company's shared SMS-provider account. Inbound replies
    ARE correctly attributed per user — check_sms_replies() filters to only
    the threads YOU personally sent, so Mike won't see Karen's reply to
    Jake's text.

    Args:
        to:      Recipient's phone number (10-digit US) or a saved contact
                 name. Accepts any format: 3865550101, 386-555-0101,
                 (386) 555-0101.
        message: Text message body (keep under 160 chars for one SMS segment).
        ctx:     MCP context (injected automatically).

    Returns:
        Confirmation, or an error string with setup instructions.

    Voice examples:
        "Text Torres that we're 20 minutes away"
        "Text David that the afternoon job is cancelled"
        "Send Karen Walsh a reminder that her appointment is tomorrow at 9am"
    """
    _telemetry_increment_tool_count("send_sms")

    # Server-mode gate — all roles permitted (see _send_sms_cap docstring).
    _sms_user = _current_user(ctx)
    _sms_allowed, _sms_why = _send_sms_cap(_sms_user)
    if not _sms_allowed:
        return f"❌ {_sms_why}"

    import re as _re

    # ── Reject a blank recipient outright ────────────────────────────────────
    # Same bug class fixed in email_invoice(): the name-resolution lookups
    # below search for `to` as a SUBSTRING of stored names, and Python
    # treats "" as a substring of everything. A blank `to` (e.g. a job
    # whose customer name failed to parse upstream, leaving an empty
    # string) must never be allowed to reach those lookups — it would
    # otherwise silently match whichever record happens to come first,
    # texting a real person's job/appointment details to the wrong
    # number. Checked before any lookup runs, not relied on per-lookup.
    if not to or not to.strip():
        return "❌ 'to' is required and cannot be blank."

    # ── Resolve a name to a phone number ───────────────────────────────────────
    # Lookup order: Customers sheet (by name/company) → users.json (crew, by
    # name) → contacts_cache (personal/per-field_crew, by name). Lets "text
    # David" or "text Torres" work without repeating numbers.
    _to_digits_check = _re.sub(r'\D', '', to)
    if len(_to_digits_check) < 10:
        _resolved_phone = None

        # 1. Customers table — match by name/company (2026-09-13 fix: this
        #    was still fully openpyxl-based, opening the old .xlsx Job
        #    Tracker directly — the third instance of the exact same bug
        #    class just fixed in _lookup_customer_email()/
        #    _lookup_invoice_customer_email(), found during the same
        #    system-wide audit. Was silently unable to find any customer
        #    added after the SQLite migration.
        try:
            _db_path_sms = _resolve_job_db_path(ctx, "")
            if _db_path_sms:
                import sqlite3 as _sqlite3_sms
                _conn_sms = _sqlite3_sms.connect(_db_path_sms)
                _conn_sms.row_factory = _sqlite3_sms.Row
                try:
                    _needle = to.strip().lower()
                    if _needle:
                        _like_sms = f"%{_needle}%"
                        _row_sms = _conn_sms.execute(
                            "SELECT phone FROM customers WHERE "
                            "(LOWER(company_name) LIKE ? OR LOWER(first_name) LIKE ? "
                            "OR LOWER(last_name) LIKE ?) "
                            "AND phone IS NOT NULL AND phone != '' LIMIT 1",
                            (_like_sms, _like_sms, _like_sms),
                        ).fetchone()
                        if _row_sms and _row_sms["phone"]:
                            _resolved_phone = _row_sms["phone"]
                finally:
                    _conn_sms.close()
        except Exception:
            pass

        # 2. users.json crew — match by name (server mode only)
        if not _resolved_phone:
            try:
                _ud_n = _load_users()
                if _ud_n and isinstance(_ud_n.get('users'), dict):
                    _needle2 = to.strip().lower()
                    # Guarded the same way step 1 already is — without
                    # this check, a blank _needle2 would match the FIRST
                    # crew member in the dict unconditionally (this was
                    # the actual bug: missing here, present in step 1).
                    if _needle2:
                        for _un in _ud_n['users'].values():
                            if isinstance(_un, dict) and _needle2 in (_un.get('name') or '').lower():
                                if _un.get('cell_phone'):
                                    _resolved_phone = _un['cell_phone']
                                    break
            except Exception:
                pass

        # 3. contacts_cache (personal, or per-field_crew in server mode)
        if not _resolved_phone:
            _contact = _contact_lookup(to, _sms_user)
            if _contact and _contact.get('phone'):
                _resolved_phone = _contact['phone']
            elif _contact:
                return (
                    f"❌ Found contact '{_contact.get('name', to)}' but no phone "
                    f"number is saved for them.\n"
                    f"Tell Claude: \"{_contact.get('name', to)}'s number is <phone>\" to add it."
                )

        if _resolved_phone:
            to = _resolved_phone
        # else: leave `to` as-is — the digit-count check below gives a clear error

    # ── Normalise phone number to 10 digits ───────────────────────────────────
    digits = _re.sub(r'\D', '', to)
    if len(digits) == 11 and digits[0] == '1':
        digits = digits[1:]
    if len(digits) != 10:
        return (
            f"❌ '{to}' does not look like a valid 10-digit US number or a "
            f"known contact/customer/crew name.\n"
            f"Provide a phone number, or save a contact first: "
            f"\"David's number is 386-555-0101\""
        )

    if not message.strip():
        return "❌ message cannot be empty."

    # ── Append callback signature if configured ───────────────────────────────
    try:
        _cfg_path = Path.home() / '.ai-prowler' / 'config.json'
        _full_cfg: dict = {}
        if _cfg_path.exists():
            import json as _jcfg
            _full_cfg = _jcfg.loads(_cfg_path.read_text(encoding='utf-8-sig'))
        _sig = _full_cfg.get('sms_callback_signature', '').strip()
        if _sig and _sig not in message:
            message = f"{message.rstrip()}\n{_sig}"
        if _full_cfg.get('sms_optout_enabled', True) and 'stop' not in message.lower():
            message = f"{message.rstrip()}\nReply STOP to opt out."
    except Exception:
        pass

    # ── Send via backend abstraction (Twilio / SignalWire / Vonage) ───────────
    try:
        from sms_backends import get_sms_backend, load_sms_config
        from sms_inbox import sms_thread_log
    except ImportError as _ie:
        return f"❌ SMS modules not found: {_ie}\nEnsure sms_backends.py and sms_inbox.py are in the AI-Prowler directory."

    _sms_cfg     = load_sms_config()
    _sms_backend = get_sms_backend(_sms_cfg)
    _sms_ok, _sms_msg = _sms_backend.validate_config()
    if not _sms_ok:
        return _sms_msg

    to_e164 = f"+1{digits}"
    _send_ok, _send_result = _sms_backend.send(to_e164, message)

    if _send_ok:
        # Log the outbound message so check_sms_inbox can route replies
        _user_id_for_log = (_sms_user or {}).get('id', 'personal') if _sms_user else 'personal'
        _provider_name   = _sms_cfg.get('sms_provider', 'twilio')
        try:
            _contact_for_log = _contact_lookup(digits, _sms_user)
            _cname_for_log   = (_contact_for_log or {}).get('name', '')
        except Exception:
            _cname_for_log = ''
        try:
            sms_thread_log(
                sent_by      = _user_id_for_log,
                to_number    = digits,
                body         = message,
                provider     = _provider_name,
                contact_name = _cname_for_log,
            )
        except Exception:
            pass
        return (
            f"✅ SMS sent via {_sms_backend.provider_name.title()}\n"
            f"   To:      {to_e164}\n"
            f"   Message: {message[:80]}{'...' if len(message) > 80 else ''}\n"
            f"   {_send_result}"
        )
    return _send_result


@mcp.tool()
def check_sms_replies(
    since_hours: int = 24,
    from_number: str = "",
    mark_read:   bool = True,
    ctx:         "Context | None" = None,
) -> str:
    """
    Check for inbound SMS replies received on your SMS number.

    V8.0.0: Reads from the local sms_inbox.json (populated by the
    /sms-webhook endpoint) instead of polling the Twilio API. Instant,
    works offline, supports all providers.

    Server mode: replies are filtered to threads you personally sent —
    Mike sees Karen's reply, Jake sees Bob's reply.

    Args:
        since_hours: How far back to look, in hours (default 24).
        from_number: Optional — filter to one sender only.
        mark_read:   If True, marks returned messages as read by you.
        ctx:         MCP context (injected automatically).

    Returns:
        A list of inbound messages, or a note that there are none.

    Voice examples:
        "Did Vicki reply to that text?"
        "Check for SMS replies"
        "Any texts come in today?"
    """
    _telemetry_increment_tool_count("check_sms_replies")

    try:
        from sms_inbox import (sms_inbox_read_for_user, sms_inbox_read,
                               sms_inbox_mark_read)
    except ImportError as _ie:
        return f"❌ SMS inbox module not found: {_ie}"

    _user    = _current_user(ctx)
    _user_id = (_user or {}).get('id', 'personal') if _user else 'personal'

    if _user:
        msgs = sms_inbox_read_for_user(_user_id, since_hours=since_hours)
    else:
        msgs = sms_inbox_read(since_hours=since_hours, from_number=from_number)

    if from_number.strip():
        import re as _re5
        _digits_f = _re5.sub(r'\D', '', from_number)
        if len(_digits_f) == 11 and _digits_f[0] == '1':
            _digits_f = _digits_f[1:]
        msgs = [m for m in msgs if _re5.sub(r'\D', '', m.get('from',''))[-10:] == _digits_f]

    # Exclude WhatsApp — use check_whatsapp_replies() for those
    msgs = [m for m in msgs if m.get('provider', '') != 'whatsapp']

    if not msgs:
        scope = f" from {from_number}" if from_number.strip() else ""
        return f"📭 No SMS replies{scope} in the last {since_hours} hour(s)."

    if mark_read:
        for m in msgs:
            try:
                sms_inbox_mark_read(m['id'], _user_id)
            except Exception:
                pass

    lines = [f"📬 {len(msgs)} SMS repl{'y' if len(msgs)==1 else 'ies'} "
             f"in the last {since_hours} hour(s):", ""]
    for m in msgs:
        from_display = m.get('contact_name') or m.get('from', 'unknown')
        lines.append(f"  From: {from_display}")
        lines.append(f"  When: {m.get('timestamp', 'unknown')[:19]}")
        lines.append(f"  Msg:  {(m.get('body') or '').strip()}")
        lines.append("")

    return '\n'.join(lines).rstrip()


@mcp.tool()
def check_sms_inbox(
    since_hours: float = 24.0,
    from_number: str   = "",
    unread_only: bool  = False,
    provider:    str   = "",
    ctx:         "Context | None" = None,
) -> str:
    """
    Check the local SMS / WhatsApp inbox for all inbound messages.

    Reads from sms_inbox.json — instant, no API call. Supports all
    providers in one place. Use provider='whatsapp' for WhatsApp only.

    Args:
        since_hours: How far back to look (default 24). Pass 0 for all.
        from_number: Filter to one sender (any format).
        unread_only: Only show messages not yet read by you.
        provider:    Filter by 'twilio', 'signalwire', 'vonage',
                     or 'whatsapp'. Empty = all.
        ctx:         MCP context (injected automatically).

    Returns:
        Formatted list of messages, or 'No messages' if empty.

    Voice examples:
        "Any messages come in?"
        "Check WhatsApp messages"
        "Any unread texts?"
    """
    _telemetry_increment_tool_count("check_sms_inbox")

    try:
        from sms_inbox import sms_inbox_read, sms_inbox_mark_read
    except ImportError as _ie:
        return f"❌ SMS inbox module not found: {_ie}"

    _user    = _current_user(ctx)
    _user_id = (_user or {}).get('id', 'personal') if _user else 'personal'

    msgs = sms_inbox_read(
        since_hours = since_hours,
        from_number = from_number,
        unread_only = unread_only,
        user_id     = _user_id,
        provider    = provider,
    )

    if not msgs:
        parts = []
        if unread_only: parts.append("unread")
        if provider:    parts.append(provider)
        scope = " ".join(parts)
        hours = f"in the last {since_hours}h" if since_hours > 0 else "ever"
        return f"📭 No {scope + ' ' if scope else ''}messages {hours}."

    lines = [f"📬 {len(msgs)} message(s):", ""]
    for m in msgs:
        prov         = m.get('provider', '')
        icon         = "💬" if prov == 'whatsapp' else "📱"
        from_display = m.get('contact_name') or m.get('from', 'unknown')
        unread_flag  = " 🔵" if _user_id not in (m.get('read_by') or []) else ""
        lines.append(f"  {icon} From: {from_display}{unread_flag}")
        lines.append(f"     When: {m.get('timestamp','')[:19]}")
        lines.append(f"     Msg:  {(m.get('body') or '').strip()}")
        lines.append("")

    return '\n'.join(lines).rstrip()


@mcp.tool()
def list_sms_consents(
    since_days:     float = 0,
    consented_only: bool  = False,
) -> str:
    """
    List SMS consent records captured via your website's consent-signup
    form, plus any STOP/START lifecycle updates from inbound SMS replies.

    Reads from sms_consent.json — instant, no API call. This is the answer
    to "who's opted in for SMS" / "give me my consent list" — it reflects
    CURRENT status (a person who signed up then later replied STOP shows
    consented=False here, not their original signup state).

    Args:
        since_days:     Only show records created in the last N days.
                        0 (default) = all records, regardless of age.
        consented_only: If True, only show currently-opted-in contacts.
                        If False (default), show everyone, including
                        people who submitted the form without checking
                        consent, or who have since opted out — useful for
                        a full audit trail, not just an SMS send list.

    Returns:
        Formatted list of consent records, or a message if none exist.

    Voice examples:
        "Who's opted in for SMS?"
        "Show me my consent list"
        "List everyone who signed up for texts this month"
    """
    _telemetry_increment_tool_count("list_sms_consents")

    try:
        from sms_consent import consent_list
    except ImportError as _ie:
        return f"❌ SMS consent module not found: {_ie}"

    records = consent_list(consented_only=consented_only, since_days=since_days)

    if not records:
        scope = "opted-in " if consented_only else ""
        window = f"in the last {since_days:g} day(s)" if since_days > 0 else "ever"
        return f"📭 No {scope}consent records {window}."

    lines = [f"📋 {len(records)} consent record(s):", ""]
    for r in records:
        status = "✅ Opted in" if r.get("consented") else "❌ Opted out"
        name   = r.get("name") or "(no name on file)"
        source = r.get("source", "")
        source_note = " (from SMS reply, no web signup)" if source == "sms_reply" and not r.get("name") else ""
        lines.append(f"  {status} — {name}{source_note}")
        lines.append(f"     Phone: {r.get('phone','')}")
        lines.append(f"     Signed up: {r.get('timestamp','')[:19]}")
        if r.get("opted_out_at"):
            lines.append(f"     Opted out: {r.get('opted_out_at','')[:19]}")
        lines.append("")

    return '\n'.join(lines).rstrip()


@mcp.tool()
def delete_sms_consent(
    phone_or_id: str,
) -> str:
    """
    Permanently delete an SMS consent record — e.g. in response to a
    CCPA/GDPR-style data removal request.

    This deletes the RECORD entirely (not just marking it opted-out). If
    you just want to record that someone opted out while keeping their
    history, that already happens automatically via a STOP reply — use
    this tool only for actual data-deletion requests.

    Args:
        phone_or_id: Phone number (any format) or the record's internal id.

    Returns:
        Confirmation string, or a message if no matching record was found.

    Voice examples:
        "Delete the consent record for 386-555-0101"
        "Remove Jane Smith's SMS consent data — she asked for it to be deleted"
    """
    _telemetry_increment_tool_count("delete_sms_consent")

    try:
        from sms_consent import consent_delete
    except ImportError as _ie:
        return f"❌ SMS consent module not found: {_ie}"

    removed = consent_delete(phone_or_id)
    if removed:
        return f"✅ Consent record for {phone_or_id} permanently deleted."
    return f"❌ No consent record found matching {phone_or_id!r}."


@mcp.tool()
def get_sms_thread(
    contact: str,
    since_hours: float = 168.0,
    ctx: "Context | None" = None,
) -> str:
    """
    Show the full two-way conversation thread with a contact.

    Combines your sent messages with their inbound replies in
    chronological order — like a phone's message history.
    Works for both SMS and WhatsApp.

    Server mode: only returns the thread if YOU are the one who last
    sent to this contact — otherwise another employee's conversation
    with the same contact would be visible to anyone who just knows or
    guesses their name/number, since threads are keyed by phone number
    company-wide, not per employee.

    Args:
        contact:     Contact name or phone number (any format).
        since_hours: How far back to include replies (default 168 = 7 days).
        ctx:         MCP context (injected automatically).

    Returns:
        Full conversation thread, or 'No thread found'.

    Voice examples:
        "Show my conversation with Karen"
        "What did I text Torres?"
    """
    _telemetry_increment_tool_count("get_sms_thread")

    try:
        from sms_inbox import sms_thread_get_with_replies
    except ImportError as _ie:
        return f"❌ SMS inbox module not found: {_ie}"

    conv = sms_thread_get_with_replies(contact, since_hours=since_hours)
    if not conv:
        return (
            f"📭 No SMS thread found for '{contact}'.\n\n"
            f"Start a conversation: \"Text {contact} that we're on our way\""
        )

    # Server mode: only show this thread if the caller is the one who
    # last sent to this contact. Threads are keyed by phone number alone
    # (not per employee), so without this check any role could pull up
    # a different employee's conversation just by naming the contact.
    _gst_user = _current_user(ctx)
    if _gst_user is not None:
        _gst_uid = _gst_user.get('id', '')
        if conv.get('last_sent_by') != _gst_uid:
            return (
                f"📭 No SMS/WhatsApp thread found for '{contact}' that you "
                f"personally sent to. (A thread with this contact may exist "
                f"for a different team member.)"
            )

    msgs  = conv.get('messages', [])
    name  = conv.get('contact_name', contact)
    prov  = conv.get('provider', '')
    lines = [
        f"💬 Conversation with {name}",
        f"   Provider: {prov.title() if prov else 'unknown'}",
        f"   {len(msgs)} message(s)  |  last 7 days",
        "─" * 45, "",
    ]
    for m in msgs:
        direction = m.get('direction', 'outbound')
        icon      = "→" if direction == 'outbound' else "←"
        who       = "You" if direction == 'outbound' else name
        ts        = (m.get('timestamp', '') or '')[:19]
        body      = (m.get('body', '') or '').strip()
        lines.append(f"  {icon} {who}  [{ts}]")
        lines.append(f"    {body}")
        lines.append("")

    return '\n'.join(lines).rstrip()


@mcp.tool()
def list_sms_contacts_with_replies(
    since_hours: float = 168.0,
    ctx: "Context | None" = None,
) -> str:
    """
    List all contacts you've texted recently, with unread reply counts.

    Shows who you've been in contact with, reply counts, and how many
    are unread — like a conversations list on your phone.

    Server mode: scoped to threads YOU personally sent — Mike sees only
    his own conversation list, not Karen's or Jake's. A brand-new user
    with no thread history yet sees everything until they've sent their
    first message, matching check_sms_replies' identical fallback.

    Args:
        since_hours: How far back to include (default 168 = 7 days).
        ctx:         MCP context (injected automatically).

    Returns:
        Formatted list of active threads with reply counts.

    Voice examples:
        "Who has replied to my texts?"
        "Any unread messages from customers?"
        "Show my recent SMS conversations"
    """
    _telemetry_increment_tool_count("list_sms_contacts_with_replies")

    try:
        from sms_inbox import sms_active_threads
    except ImportError as _ie:
        return f"❌ SMS inbox module not found: {_ie}"

    threads = sms_active_threads(since_hours=since_hours)

    # Server mode: scope to threads THIS user has sent to — same ownership
    # check sms_inbox_read_for_user() already uses for check_sms_replies
    # (last_sent_by == user_id). Without this, any role — including
    # field_crew — would see every active SMS conversation company-wide.
    # New user with no thread history yet: fall back to showing everything,
    # matching sms_inbox_read_for_user()'s identical fallback so both tools
    # behave consistently for a brand-new employee.
    _user = _current_user(ctx)
    if _user is not None:
        _uid = _user.get("id", "")
        _own_threads = [t for t in threads if t.get("last_sent_by") == _uid]
        if _own_threads:
            threads = _own_threads

    if not threads:
        return f"📭 No SMS activity in the last {since_hours:.0f} hours."

    lines = [f"📱 {len(threads)} active SMS thread(s):", ""]
    for t in threads:
        name   = t.get('contact_name') or t.get('thread_id', 'unknown')
        prov   = t.get('provider', '')
        unread = t.get('unread_replies', 0)
        total  = t.get('total_replies', 0)
        unread_str = f"  🔵 {unread} unread" if unread else ""
        lines.append(f"  • {name}{unread_str}")
        if total:
            lines.append(f"    {total} repl{'y' if total==1 else 'ies'} received")
        if prov:
            lines.append(f"    via {prov.title()}")
        lines.append("")

    return '\n'.join(lines).rstrip()


@mcp.tool()
def send_whatsapp(
    to:      str,
    message: str,
    ctx:     "Context | None" = None,
) -> str:
    """
    Send a WhatsApp message via Twilio's WhatsApp API.

    Uses the same Twilio credentials as send_sms — no separate
    account needed. Works worldwide without carrier restrictions.

    Args:
        to:      Recipient's phone number or contact name.
        message: Message text (up to 4096 chars for WhatsApp).
        ctx:     MCP context (injected automatically).

    Returns:
        Confirmation, or setup instructions if not configured.

    Voice examples:
        "WhatsApp Karen that the crew is 10 minutes out"
        "Send Torres a WhatsApp with the job details"
    """
    _telemetry_increment_tool_count("send_whatsapp")

    _wa_user = _current_user(ctx)
    _wa_allowed, _wa_why = _send_sms_cap(_wa_user)
    if not _wa_allowed:
        return f"❌ {_wa_why}"

    try:
        from sms_backends import get_whatsapp_backend, load_sms_config
        from sms_inbox import sms_thread_log
    except ImportError as _ie:
        return f"❌ SMS modules not found: {_ie}"

    _wa_cfg     = load_sms_config()
    _wa_backend = get_whatsapp_backend(_wa_cfg)
    _wa_ok, _wa_hint = _wa_backend.validate_config()
    if not _wa_ok:
        return _wa_hint

    import re as _re_wa
    _wa_digits = _re_wa.sub(r'\D', '', to)
    if len(_wa_digits) < 10:
        _wa_contact = _contact_lookup(to, _wa_user)
        if _wa_contact and _wa_contact.get('phone'):
            to = _wa_contact['phone']

    _wa_send_ok, _wa_result = _wa_backend.send(to, message)

    if _wa_send_ok:
        _wa_user_id = (_wa_user or {}).get('id', 'personal') if _wa_user else 'personal'
        try:
            sms_thread_log(
                sent_by      = _wa_user_id,
                to_number    = to,
                body         = message,
                provider     = 'whatsapp',
                contact_name = '',
            )
        except Exception:
            pass
        return (
            f"✅ WhatsApp message sent\n"
            f"   To:      {to}\n"
            f"   Message: {message[:80]}{'...' if len(message) > 80 else ''}\n"
            f"   {_wa_result}"
        )
    return _wa_result


@mcp.tool()
def check_whatsapp_replies(
    since_hours: float = 24.0,
    from_number: str   = "",
    ctx: "Context | None" = None,
) -> str:
    """
    Check for inbound WhatsApp messages.

    Reads from the local inbox (populated by /whatsapp-webhook) —
    instant, no API call. Shows only WhatsApp messages, not SMS.

    Server mode: scoped to threads YOU personally sent — same per-user
    isolation as check_sms_replies. Mike sees Karen's WhatsApp reply,
    not Jake's.

    Args:
        since_hours: How far back to look (default 24).
        from_number: Filter to one contact (number or name).
        ctx:         MCP context (injected automatically).

    Returns:
        List of inbound WhatsApp messages, or 'No messages'.

    Voice examples:
        "Any WhatsApp replies?"
        "Did Karen reply on WhatsApp?"
    """
    _telemetry_increment_tool_count("check_whatsapp_replies")

    try:
        from sms_inbox import sms_inbox_read, sms_inbox_read_for_user
    except ImportError as _ie:
        return f"❌ SMS inbox module not found: {_ie}"

    _wr_user    = _current_user(ctx)
    _wr_user_id = (_wr_user or {}).get('id', 'personal') if _wr_user else 'personal'

    # Server mode: scope to threads THIS user has sent to — same ownership
    # check check_sms_replies() already uses. Closes a bypass where this
    # tool previously called check_sms_inbox() directly (a plain Python
    # function call that skips MCP-level Tier A suppression entirely),
    # giving every role an unscoped, company-wide dump filtered only by
    # provider, not by who's asking.
    if _wr_user:
        _wr_msgs = sms_inbox_read_for_user(_wr_user_id, since_hours=since_hours)
        _wr_msgs = [m for m in _wr_msgs if m.get('provider', '') == 'whatsapp']
        if from_number.strip():
            import re as _re6
            _wr_digits = _re6.sub(r'\D', '', from_number)
            if len(_wr_digits) == 11 and _wr_digits[0] == '1':
                _wr_digits = _wr_digits[1:]
            _wr_msgs = [m for m in _wr_msgs
                       if _re6.sub(r'\D', '', m.get('from', ''))[-10:] == _wr_digits]
    else:
        _wr_msgs = sms_inbox_read(
            since_hours = since_hours,
            from_number = from_number,
            unread_only = False,
            user_id     = _wr_user_id,
            provider    = 'whatsapp',
        )

    if not _wr_msgs:
        hours = f"in the last {since_hours}h" if since_hours > 0 else "ever"
        return f"📭 No whatsapp messages {hours}."

    lines = [f"📬 {len(_wr_msgs)} message(s):", ""]
    for m in _wr_msgs:
        from_display = m.get('contact_name') or m.get('from', 'unknown')
        unread_flag  = " 🔵" if _wr_user_id not in (m.get('read_by') or []) else ""
        lines.append(f"  💬 From: {from_display}{unread_flag}")
        lines.append(f"     When: {m.get('timestamp','')[:19]}")
        lines.append(f"     Msg:  {(m.get('body') or '').strip()}")
        lines.append("")

    return '\n'.join(lines).rstrip()


# ══════════════════════════════════════════════════════════════════════════════
# ACTION TOOL 10 — schedule_next_recurring_job
# ══════════════════════════════════════════════════════════════════════════════

@mcp.tool()
def schedule_next_recurring_job(
    job_identifier: str,
    filepath:       str = "",
    when:           str = "",
    ctx: "Context | None" = None,
) -> str:
    """
    Auto-create the next recurring job after a job is marked complete.

    Looks up the completed job to find the customer, then reads the customer's
    service frequency (Weekly / Biweekly / Monthly / Quarterly / One-time) from
    the Customers sheet and calculates the next service date accordingly.
    Writes the new job row to Jobs_Schedule and returns the new JobID.

    Handles all standard frequencies:
      W  / Weekly      → +7 days
      BW / Biweekly    → +14 days
      M  / Monthly     → +1 month (same day)
      Q  / Quarterly   → +3 months (same day)
      OT / One-time    → no next job created

    Args:
        job_identifier: JobID (e.g. "JOB-0001") or customer name/company.
        filepath:       Path to the SQLite job database. Uses default if omitted.
                         In server mode this argument is ignored — see
                         _resolve_job_db_path().
        when:           Which jobs to search among — works in BOTH personal
                         and server mode: "today" (default if omitted),
                         "tomorrow", "yesterday", "this_week", "next_week",
                         "any" (no date restriction), or an explicit
                         "YYYY-MM-DD" date.

    Server mode: field_crew only search jobs assigned to THEM (Crew /
    Technician matches their own name) — owner/manager/staff search every
    crew's jobs. This crew restriction applies regardless of `when` and does
    not apply at all in personal mode (single user).

    Returns:
        New JobID and scheduled date, or explanation if no recurring job applies.

    Voice examples:
        "Schedule the next recurring job after JOB-0003"
        "Set up the next job for Blue Wave Cafe"
        "Auto-book the next visit after today's Sunshine Realty job"
        "Schedule the next job after the one I did yesterday"
        "Reschedule next week's Crabby's job"
    """
    # Serialise the whole load -> modify -> save cycle so two concurrent
    # server-mode writers can never interleave and silently drop each
    # other's changes (openpyxl has no file locking of its own).
    with _spreadsheet_write_lock:
        return _schedule_next_recurring_job_impl(job_identifier, filepath, when, ctx)


def _srj_resolve_date_range(when: str, today):
    """
    Resolve a human date-range keyword into an inclusive (start, end) date
    range for scoping schedule_next_recurring_job()'s job search.

    Returns (None, None) for "any" — no date restriction at all.
    Falls back to (today, today) for anything unrecognised, since "today"
    is the safe default this tool is normally used for.
    """
    import datetime as _dt
    w = (when or "today").strip().lower().replace("-", "_").replace(" ", "_")
    if w in ("any", "all", ""):
        return (None, None)
    if w == "today":
        return (today, today)
    if w == "tomorrow":
        d = today + _dt.timedelta(days=1)
        return (d, d)
    if w == "yesterday":
        d = today - _dt.timedelta(days=1)
        return (d, d)
    if w in ("this_week", "thisweek"):
        start = today - _dt.timedelta(days=today.weekday())  # Monday
        end   = start + _dt.timedelta(days=6)                # Sunday
        return (start, end)
    if w in ("next_week", "nextweek"):
        start = today - _dt.timedelta(days=today.weekday()) + _dt.timedelta(days=7)
        end   = start + _dt.timedelta(days=6)
        return (start, end)
    # Explicit date, e.g. "2026-07-15"
    try:
        d = _dt.datetime.strptime(w.replace("_", "-"), "%Y-%m-%d").date()
        return (d, d)
    except ValueError:
        pass
    return (today, today)


def _schedule_next_recurring_job_impl(job_identifier: str, filepath: str, when: str, ctx) -> str:
    """Implementation body, called under _spreadsheet_write_lock. See
    schedule_next_recurring_job() for the public docstring.

    Job Board Architecture Spec Phase 1 (spec §5, §11): internals now use
    the SQLite-backed db_write_ops.db_schedule_next_recurring_job instead
    of an openpyxl double-sheet (Jobs_Schedule + Customers) scan. Date-
    range resolution (_srj_resolve_date_range) and the crew-scoping
    decision below are pure/ctx-derived logic with no storage dependency
    and are unchanged; only the job lookup, frequency lookup, and new-
    job creation moved to db_write_ops.
    """
    _telemetry_increment_tool_count("schedule_next_recurring_job")

    import datetime as _dt
    from db_write_ops import db_schedule_next_recurring_job

    db_path = _resolve_job_db_path(ctx, filepath)
    if not db_path:
        return "❌ No spreadsheet path configured."

    # ── Scoping ─────────────────────────────────────────────────────────────
    # field_crew (server mode only): only search jobs assigned to THEM
    # (Crew / Technician matches their own name) — prevents accidentally
    # rescheduling a coworker's job by a job-name/JobID match alone.
    # Owner/manager/staff see every crew's jobs (see the 2026-09-24 fix note
    # just below — staff was previously mis-restricted here by mistake).
    # This crew restriction never applies in personal mode (single user).
    #
    # Date range (`when`): a common feature in BOTH modes now. If the caller
    # doesn't specify one: server mode defaults to "today" (this tool is
    # normally called right after finishing a job); personal mode defaults
    # to "any" (unrestricted) so every version before this parameter existed
    # keeps working unchanged. An explicitly-passed `when` behaves
    # identically in both modes.
    # ── Scoping (fixed 2026-09-24) ──────────────────────────────────────────
    # Previously used _check_db_cap(user, "full") — a DB-MANAGEMENT capability
    # check (index/untrack/reindex/update), not a job-crew-ownership check —
    # to decide job-scheduling restriction. _check_db_cap only grants "full"
    # to owner/manager, so staff (which gets "limited") was being restricted
    # to their own jobs here, inconsistent with every other job-tracker tool
    # in this file (create_invoice, read_job_spreadsheet, update_job_spreadsheet,
    # the whole delete_* family, the route-management family), all of which use
    # the shared _job_crew_scope() helper — which correctly treats staff as
    # unrestricted (same tier as owner/manager for job/crew data) and only
    # restricts field_crew. Switched to that same helper so this tool matches
    # the rest of the codebase instead of its own one-off rule.
    _srj_effective_when = when.strip() if when and when.strip() else "today"
    _srj_range_start, _srj_range_end = _srj_resolve_date_range(
        _srj_effective_when, _dt.date.today())

    restrict, _srj_crew_name = _job_crew_scope(ctx, db_path)

    actor = _actor_display_name(ctx)
    return db_schedule_next_recurring_job(
        db_path, job_identifier, actor,
        restrict=restrict, crew_name=_srj_crew_name,
        range_start=_srj_range_start.isoformat() if _srj_range_start else None,
        range_end=_srj_range_end.isoformat() if _srj_range_end else None,
    )


# ══════════════════════════════════════════════════════════════════════════════
# ACTION TOOL 10b — find_stale_customers / send_customer_reminders
# ══════════════════════════════════════════════════════════════════════════════
# The Reports screen's "Customer Reminders" section (2026-09-23, at the
# owner's request). Owner-only (see _owner_only_denied) — same access level
# as the rest of Reports. find_stale_customers is the search; send_customer_
# reminders is the explicit, reviewed send — the daily digest hook
# (_maybe_send_stale_customer_digest, wired into read_job_spreadsheet /
# get_board_updates) only ever tells the owner who's due, it never contacts a
# customer on its own.

@mcp.tool()
def find_stale_customers(days_threshold: int = -1, filepath: str = "", ctx: "Context | None" = None) -> str:
    """
    Lists Active customers who haven't had a Completed job in days_threshold+
    days — or have never had one at all — most-overdue first. This is the
    search behind the Jobs app's Reports -> Customer Reminders section; use
    send_customer_reminders() afterward to actually message the ones worth
    reaching out to.

    "Last serviced" comes from the job history itself (the most recent
    Completed job's Service Date), not the Customers sheet's own hand-
    maintained "Last Service Date" field, which can drift out of date.

    Server mode: owner, managers and staff (R-069, David 2026-09-29: "Customer
    reminders should be visible for owner, managers, and staff as it's only
    informational"); field crew get a clear denial. SENDING a reminder
    (send_customer_reminders) is still owner-only. Unrestricted in personal mode.

    Args:
        days_threshold: How many days since last service counts as "due".
                        -1 (default) reads the "Stale Customer Reminder
                        Days" Settings value (60 if that's never been set).
                        Pass an explicit number to check a different window
                        without changing the saved setting.
        filepath:       Path to the SQLite job database. Uses the default
                        from Settings if omitted. In server mode this
                        argument is ignored.
        ctx:            MCP context (injected automatically).

    Returns:
        A ✅ list (customer, last serviced / never serviced, days overdue),
        or a ✅ "nobody's due" message when none qualify, or a ❌ for field crew.

    Voice examples:
        "Which active customers haven't been serviced in 90 days?"
        "Find customers due for a check-in"
    """
    denial = _field_crew_data_admin_denied(ctx, "Customer Reminders")   # R-069
    if denial:
        return denial
    db_path = _resolve_job_db_path(ctx, filepath)
    if not db_path:
        return "❌ No spreadsheet path configured."

    from db_write_ops import db_find_stale_customers, db_read_settings_stale_customer_days
    threshold = days_threshold if days_threshold is not None and days_threshold >= 0 else None
    effective = threshold if threshold is not None else db_read_settings_stale_customer_days(db_path)
    stale = db_find_stale_customers(db_path, days_threshold=threshold)
    if not stale:
        return f"✅ No active customers are due for a check-in (threshold: {effective}+ days)."

    lines = [f"✅ {len(stale)} active customer(s) due for a check-in (threshold: {effective}+ days):"]
    for c in stale:
        when = f"{c['days_since']} days ago" if c["days_since"] is not None else "never serviced"
        contact = c["email"] or c["phone"] or "no contact on file"
        # Names the actual contact person too, when it differs from the
        # business name — so the owner can see who the reminder will
        # actually greet before sending it. CustomerID comes right after the
        # bullet, always a single space-free token — this is what the Jobs
        # PWA's own line parser (findStaleCustomers() in jobs/index.html)
        # anchors on; keep the two in lock-step if this format ever changes.
        greet = c.get("contact_name") or c["name"]
        who = f"{c['name']} (contact: {greet})" if greet != c["name"] else c["name"]
        lines.append(f"  • {c['customer_id']} — {who} — last serviced {when} — {contact}")
    return "\n".join(lines)


@mcp.tool()
def send_customer_reminders(
    customer_ids: str,
    channel:      str = "email",
    message:      str = "",
    filepath:     str = "",
    ctx: "Context | None" = None,
) -> str:
    """
    Sends a check-in reminder — asking whether service is needed — to one or
    more customers found by find_stale_customers(). This is the explicit,
    reviewed send step; nothing texts or emails a customer automatically on
    its own (the daily digest only ever notifies the OWNER of who's due).

    Uses each customer's own Email (channel="email") or Phone (channel=
    "sms") on file, via send_email()/send_sms() — the same tools everything
    else in AI-Prowler uses to reach a customer. A customer missing the
    contact field for the chosen channel is skipped and named in the result,
    not silently dropped.

    The greeting uses the actual PERSON to reach, not the account name — a
    residential customer's First Name, or for a commercial account with no
    named individual on file, the On-Site Contact; only falls back to the
    company/account name when neither is on file. "Hi Jane," reads like
    someone wrote it; "Hi Riverside Grill," reads like a form letter.

    Owner only, in server mode — same access level as the rest of Reports.
    Unrestricted in personal mode.

    Args:
        customer_ids: Comma-separated CustomerIDs (e.g. "CUST-0001,CUST-0002")
                      — from find_stale_customers()'s own output.
        channel:      "email" (default) or "sms". Each channel has its own
                      Settings toggle ("Customer Reminder Email Enabled" /
                      "Customer Reminder SMS Enabled", both default Enabled)
                      — a disabled channel returns a clear ❌ naming which
                      setting to flip, rather than silently sending nothing.
        message:      Custom message. Leave blank for the default: "Hi
                      {name}, it's been a while since your last
                      service{ - on {date}, if known}. Would you like to
                      schedule your next visit? Just reply to let us know."
                      A custom message may use {name} and {date} as
                      placeholders (the contact's name / their last service
                      date, or "your last visit" when there's no date on
                      file) — each recipient still gets their own name/date
                      substituted in, even with a custom message. Plain text
                      with no placeholders is sent verbatim to everyone.
        filepath:     Path to the SQLite job database. Uses the default from
                      Settings if omitted. In server mode this argument is
                      ignored.
        ctx:          MCP context (injected automatically).

    Returns:
        A ✅ summary of who was messaged, plus anyone skipped and why
        (missing contact info, send failure) — or a ❌ if the caller isn't
        the owner.

    Voice examples:
        "Email a service reminder to CUST-0004 and CUST-0011"
        "Text CUST-0007 asking if they need service"
    """
    denial = _owner_only_denied(ctx)
    if denial:
        return denial
    db_path = _resolve_job_db_path(ctx, filepath)
    if not db_path:
        return "❌ No spreadsheet path configured."

    ids = [c.strip() for c in (customer_ids or "").split(",") if c.strip()]
    if not ids:
        return "❌ customer_ids is required — pass one or more CustomerIDs, comma-separated."
    channel_norm = (channel or "email").strip().lower()
    if channel_norm not in ("email", "sms"):
        return "❌ channel must be 'email' or 'sms'."

    from db_write_ops import (
        db_find_stale_customers,
        db_read_settings_customer_reminder_email_enabled,
        db_read_settings_customer_reminder_sms_enabled,
    )
    # Per-channel gate (2026-09-23, at the owner's request — "enable email
    # send and enable SMS send as part of the Customer Reminder
    # configuration"). Checked here, not in find_stale_customers — searching
    # is never blocked, only the explicit send. Independent settings: either,
    # both, or neither channel can be on.
    channel_enabled = (
        db_read_settings_customer_reminder_email_enabled(db_path) if channel_norm == "email"
        else db_read_settings_customer_reminder_sms_enabled(db_path)
    )
    if not channel_enabled:
        setting_name = "Customer Reminder Email Enabled" if channel_norm == "email" else "Customer Reminder SMS Enabled"
        return f"❌ {channel_norm.upper()} reminders are turned off. Enable \"{setting_name}\" in Settings to use this channel."
    # Looked up fresh rather than trusting whatever the caller's customer_ids
    # claim — this is also how each customer's contact_name/contact info/
    # last-serviced date get resolved for the message itself.
    by_id = {c["customer_id"]: c for c in db_find_stale_customers(db_path, days_threshold=0)}

    sent, skipped = [], []
    custom_template = message.strip() if message and message.strip() else None
    for cid in ids:
        c = by_id.get(cid)
        if not c:
            skipped.append(f"{cid} (not found or not currently an active customer)")
            continue
        contact = c["email"] if channel_norm == "email" else c["phone"]
        if not contact:
            skipped.append(f"{c['name']} ({cid}) — no {'email' if channel_norm == 'email' else 'phone number'} on file")
            continue
        greet_name = c.get("contact_name") or c["name"]
        date_text = c["last_service_date"] or "your last visit"
        if custom_template:
            # {name}/{date} are optional — plain text with neither is sent
            # verbatim, same as before this feature existed.
            body = custom_template.replace("{name}", greet_name).replace("{date}", date_text)
        else:
            when_clause = f" — your last service was on {c['last_service_date']}" if c["last_service_date"] else ""
            body = (
                f"Hi {greet_name}, it's been a while since your last service{when_clause}. "
                "Would you like to schedule your next visit? Just reply to let us know."
            )
        try:
            if channel_norm == "email":
                result = send_email(contact, "Time for your next service?", body, ctx=ctx)
            else:
                result = send_sms(contact, body, ctx=ctx)
            if _isinstance_failure(result):
                skipped.append(f"{c['name']} ({cid}) — send failed: {result.splitlines()[0]}")
            else:
                sent.append(f"{c['name']} ({cid})")
        except Exception as exc:
            skipped.append(f"{c['name']} ({cid}) — send failed: {exc}")

    lines = [f"✅ Reminder {'emailed' if channel_norm == 'email' else 'texted'} to {len(sent)} customer(s)."]
    if sent:
        lines.extend(f"  • {s}" for s in sent)
    if skipped:
        lines.append(f"⚠️ Skipped {len(skipped)}:")
        lines.extend(f"  • {s}" for s in skipped)
    return "\n".join(lines)


def _isinstance_failure(result) -> bool:
    """send_email/send_sms both return a plain string, ❌-prefixed on
    failure — same convention _isFailureResult() checks client-side."""
    return isinstance(result, str) and result.strip().startswith("❌")


# ══════════════════════════════════════════════════════════════════════════════
# ACTION TOOL 11 — log_time_entry
# ══════════════════════════════════════════════════════════════════════════════

@mcp.tool()
def log_time_entry(
    job_identifier: str,
    action:         str,
    filepath:       str = "",
    gps_coords:     str = "",
    ctx: "Context | None" = None,
) -> str:
    """
    Clock in or out for a job. Records timestamps to the TimeLog sheet for
    accurate job costing, crew payroll, and actual-vs-estimated duration.

    On clock-out, automatically calculates elapsed minutes and writes the
    Actual Duration back to the Jobs_Schedule sheet.

    Args:
        job_identifier: JobID (e.g. "JOB-0001") or customer name.
        action:         "start" to clock in, "stop" to clock out.
        filepath:       Path to the SQLite job database. Uses default if omitted.
                         In server mode this argument is ignored — see
                         _resolve_job_db_path().
        gps_coords:     Optional GPS coordinates string "lat,lng" to log
                         with the clock-in or clock-out entry. Passed
                         automatically by the Jobs App PWA.

    Returns:
        Confirmation with timestamp and elapsed time (on stop), or error.

    Voice examples:
        "Clock in for JOB-0003"
        "Start the timer for Blue Wave Cafe"
        "Clock out — I just finished the Harbor Inn job"
        "Stop the timer for JOB-0001"
    """
    # Serialise the whole load -> modify -> save cycle so two concurrent
    # server-mode writers (e.g. two crew members clocking in/out at once)
    # can never interleave and silently drop each other's changes.
    with _spreadsheet_write_lock:
        return _log_time_entry_impl(job_identifier, action, filepath, ctx, gps_coords)


def _gps_maps_hyperlink(cell, coords: str) -> None:
    """If `coords` looks like "lat,lng", turn the cell into a clickable
    link to that location on Google Maps. The displayed value is left
    exactly as-is (still plain "lat,lng" text, still copyable) — only a
    hyperlink target and light blue/underline styling are added, so the
    TimeLog sheet's Clock In GPS / Clock Out GPS columns can be clicked
    straight through to verify location without leaving the spreadsheet.
    Silently does nothing for blank/malformed coordinate strings.
    """
    coords = (coords or "").strip()
    if not coords or "," not in coords:
        return
    try:
        lat_s, lng_s = coords.split(",", 1)
        float(lat_s.strip()); float(lng_s.strip())
    except ValueError:
        return
    from openpyxl.styles import Font as _GpsFont
    cell.hyperlink = f"https://www.google.com/maps?q={lat_s.strip()},{lng_s.strip()}"
    cell.font = _GpsFont(color="0563C1", underline="single")


def _log_time_entry_impl(job_identifier: str, action: str, filepath: str, ctx, gps_coords: str = "") -> str:
    """Implementation body, called under _spreadsheet_write_lock. See
    log_time_entry() for the public docstring.

    Job Board Architecture Spec Phase 1 (spec §5, §11): internals now use
    the SQLite-backed db_write_ops.db_log_time_entry instead of an
    openpyxl load/mutate/save cycle on the TimeLog sheet. This also picks
    up the Phase 1 regression-test requirement called out in spec §11:
    "own open entry" ownership is now a real crew_user_id foreign-key
    match rather than name-matching against a free-text "Crew /
    Technician" cell (the old "Logged By (User ID)" column was optional
    and frequently absent, so that equality could never hold in either
    direction — see the v9.1.x fix note this function used to carry).
    Elapsed-minutes math, Actual Duration writeback to jobs, and the
    ⏱️ Clocked IN/OUT return format are unchanged.
    """
    _telemetry_increment_tool_count("log_time_entry")

    from db_write_ops import db_log_time_entry

    action = (action or "").strip().lower()
    if action not in ("start", "stop"):
        return "❌ action must be 'start' or 'stop'."

    db_path = _resolve_job_db_path(ctx, filepath)
    if not db_path:
        return "❌ No spreadsheet path configured."

    # ── Server-mode crew scoping — kept for parity with the previous
    #    implementation (currently advisory only: Crew / Technician is
    #    scheduling reference, not access control, same as before). ─────
    _job_crew_scope(ctx, db_path)

    _lte_user = _current_user(ctx)
    _lte_uid = _lte_user.get('id', '') if _lte_user else ''
    _lte_display = _lte_user.get('name', _lte_uid) if _lte_user else ''

    backup_msg = _backup_job_db(db_path)

    result = db_log_time_entry(
        db_path, job_identifier, action,
        user_id=_lte_uid, user_display_name=_lte_display, gps_coords=gps_coords or "",
    )
    if backup_msg and result.startswith("⏱️"):
        result = f"{result}\n   {backup_msg}"
    return result


# ══════════════════════════════════════════════════════════════════════════════
# ACTION TOOL 11.5 — get_daily_mileage
# ══════════════════════════════════════════════════════════════════════════════

@mcp.tool()
def get_daily_mileage(
    entry_date: str,
    crew:       str = "",
    filepath:   str = "",
    ctx: "Context | None" = None,
) -> str:
    """
    Estimate actual miles driven on a given day, computed from real GPS
    points already captured at clock-in/clock-out (log_time_entry's
    gps_coords, passed automatically by the Jobs PWA) — NOT continuous
    background tracking. A browser-based PWA (not a native app) generally
    can't track GPS continuously in the background; iOS Safari in
    particular suspends location the moment the tab isn't the active
    foreground app, so a true always-on odometer isn't realistic here.

    What this actually computes: for each crew member, orders that day's
    TimeLog entries chronologically, then for every consecutive pair where
    the earlier entry's Clock Out GPS and the later entry's Clock In GPS
    are BOTH present, calls OSRM (the same free routing service
    build_daily_route()/optimize_route() already use) for the real driving
    distance between those two points and adds it to that crew member's
    running total. This captures the drive BETWEEN jobs (clock-out at job
    A -> clock-in at job B) — not any driving before the first clock-in or
    after the last clock-out of the day, since there's no GPS point
    marking those.

    Entries missing either GPS point are skipped (not estimated, not
    guessed) and listed separately so gaps in the day's mileage are
    visible rather than silently invented.

    If filepath is omitted, the default database path configured in
    the database's fixed, automatically-resolved location is used.

    Args:
        entry_date: Date to compute mileage for, e.g. "2026-09-22".
        crew:       Optional — limit to one crew member's entries. If
                    omitted, every crew member who clocked in/out that day
                    gets their own mileage total.
        filepath:   Path to the SQLite job database. Uses the default if
                    omitted.

    Returns:
        A per-crew mileage breakdown (each counted leg with its distance),
        totals, and a note listing any legs skipped for missing GPS data —
        or a clear message if no time entries exist for that date.

    Voice examples:
        "How many miles did Carlos drive today?"
        "What's our total mileage for September 22nd?"
    """
    _telemetry_increment_tool_count("get_daily_mileage")
    return _get_daily_mileage_impl(entry_date=entry_date, crew=crew, filepath=filepath, ctx=ctx)


def _get_daily_mileage_impl(entry_date: str, crew: str, filepath: str, ctx) -> str:
    import requests as _req
    import datetime as _mdt
    from db_access import get_connection

    db_path = _resolve_job_db_path(ctx, filepath)
    if not db_path:
        return "❌ No database path provided and no default path configured."

    try:
        target_date = _mdt.datetime.strptime(entry_date.strip(), "%Y-%m-%d").date()
    except ValueError:
        return f"❌ entry_date must be YYYY-MM-DD format, got: {entry_date!r}"

    conn = get_connection(db_path)
    try:
        rows = conn.execute(
            "SELECT entry_id, crew, clock_in, clock_out, clock_in_gps, clock_out_gps "
            "FROM time_entries WHERE entry_date = ? ORDER BY crew, clock_in",
            (target_date.isoformat(),),
        ).fetchall()
    finally:
        conn.close()

    if crew.strip():
        crew_filter = crew.strip().lower()
        rows = [r for r in rows if (r["crew"] or "").strip().lower() == crew_filter]

    if not rows:
        crew_note = f" for {crew!r}" if crew.strip() else ""
        return f"ℹ️  No TimeLog entries found for {target_date.isoformat()}{crew_note}."

    def _parse_gps(raw):
        if not raw or "," not in str(raw):
            return None
        try:
            lat_s, lon_s = str(raw).split(",", 1)
            return float(lat_s.strip()), float(lon_s.strip())
        except ValueError:
            return None

    # Group by crew — the SQL query above already sorts by (crew,
    # clock_in), so appending in query order keeps each crew's entries
    # chronological within its own group.
    by_crew = {}
    for r in rows:
        by_crew.setdefault((r["crew"] or "").strip() or "(unassigned)", []).append(r)

    lines = [f"🚗 Mileage for {target_date.isoformat()}", "─" * 50]
    grand_total_miles = 0.0
    any_legs_counted = False

    for crew_name, entries in by_crew.items():
        lines.append(f"\n{crew_name}:")
        crew_total_miles = 0.0
        skipped = []
        legs_counted = 0
        for i in range(len(entries) - 1):
            prev, nxt = entries[i], entries[i + 1]
            out_pt = _parse_gps(prev["clock_out_gps"])
            in_pt = _parse_gps(nxt["clock_in_gps"])
            if out_pt is None or in_pt is None:
                missing = "Clock Out GPS" if out_pt is None else "Clock In GPS"
                skipped.append(
                    f"  (skipped: {prev['entry_id']} -> {nxt['entry_id']} — missing {missing})"
                )
                continue
            try:
                coord_str = f"{out_pt[1]},{out_pt[0]};{in_pt[1]},{in_pt[0]}"
                resp = _req.get(
                    f"http://router.project-osrm.org/route/v1/driving/{coord_str}",
                    params={"overview": "false", "annotations": "false"},
                    timeout=30,
                ).json()
                if resp.get("code") != "Ok":
                    skipped.append(
                        f"  (skipped: {prev['entry_id']} -> {nxt['entry_id']} — routing error)"
                    )
                    continue
                leg_miles = resp["routes"][0]["distance"] * 0.000621371
            except Exception as exc:
                skipped.append(f"  (skipped: {prev['entry_id']} -> {nxt['entry_id']} — {exc})")
                continue
            crew_total_miles += leg_miles
            legs_counted += 1
            any_legs_counted = True
            lines.append(
                f"  {prev['entry_id']} -> {nxt['entry_id']}: {leg_miles:.1f} mi "
                f"(clock-out {prev['clock_out']} -> clock-in {nxt['clock_in']})"
            )
        lines.extend(skipped)
        lines.append(f"  Subtotal: {crew_total_miles:.1f} mi ({legs_counted} leg(s) counted)")
        grand_total_miles += crew_total_miles

    lines.append("")
    lines.append(f"TOTAL: {grand_total_miles:.1f} mi across {len(by_crew)} crew member(s)")
    if not any_legs_counted:
        lines.append(
            "\nℹ️  No legs could be computed — every consecutive clock-out/"
            "clock-in pair that day was missing a GPS point on at least "
            "one side. Mileage tracking needs GPS to be captured at both "
            "clock-in and clock-out (the Jobs PWA does this automatically "
            "when location permission is granted)."
        )
    lines.append(
        "\nℹ️  This is driving BETWEEN jobs only (clock-out at one job to "
        "clock-in at the next) — it doesn't include any driving before "
        "the day's first clock-in or after the last clock-out, since "
        "there's no recorded GPS point marking those."
    )
    return "\n".join(lines)


