# ══════════════════════════════════════════════════════════════════════════════
# EMAIL TOOLS  (v7.1.0)
# ══════════════════════════════════════════════════════════════════════════════
# SMTP Option-A implementation: Python stdlib only (smtplib + email + ssl).
# One-time configure_email() stores credentials in ~/.ai-prowler/email_config.json
# (password stored base64-obfuscated, same pattern as the bearer token file).
# All subsequent email tools (send_email, send_alert, send_learnings_report,
# send_file) pick up the stored config automatically.
#
# Server-mode safety (v8.0.0): ALL roles may use send_email / send_alert /
# send_learnings_report — owner, manager, staff, and field_crew all have
# can_send_email=True. configure_email and send_file remain personal-only
# (configure_email reconfigures SMTP; send_file attaches arbitrary files).
#
# RECIPIENT SOURCES for field_crew in server mode:
#   Email (send_email / send_alert):
#     1. Customers sheet — matched by name, company, CustomerID, or email address.
#        The 'Email' column is used automatically; no need to know the address.
#     2. Registered server users — matched by email address or name (users.json).
#   SMS (send_sms):
#     1. users.json crew records — cell_phone + cell_carrier → gateway auto-resolved.
#     2. Customers sheet — Phone column match; SMS Gateway (pinned) or
#        Cell Carrier column → gateway auto-resolved via _carrier_to_gateway().
#     3. contacts_cache.json — saved contacts with a manually pinned gateway.
#     4. Twilio (paid) — unrestricted, any US number.
# ══════════════════════════════════════════════════════════════════════════════

import base64 as _b64

def _EMAIL_CONFIG_PATH() -> Path:
    return _state_dir() / "email_config.json"


def _CONTACTS_CACHE_PATH(user: "dict | None" = None) -> Path:
    """Personal contacts directory — one entry per person, holding phone,
    email, SMS gateway, and carrier together so a name like 'David' or
    'Vicki' resolves directly to everything needed to reach them.

    Structure:
    {
      "contacts": {
        "david": {"phone": "4807470358", "email": "david@x.com",
                   "gateway": "txt.att.net", "carrier": "AT&T Mobility LLC"},
        "vicki": {"phone": "4805437595", "email": "", "gateway": "vtext.com",
                   "carrier": ""}
      }
    }
    Looked up by name (case-insensitive) or by 10-digit phone number,
    whichever the caller has on hand.

    Personal mode (user=None): single shared contacts_cache.json — there's
    only one person using this install, so there's nothing to separate.

    Server mode (user is not None): EVERY role gets its own private,
    per-user file (contacts_cache_<username>.json) — owner, manager, staff,
    and field_crew all save and look up contacts independently of each
    other. This matters because v8.0.0 opened email/SMS/WhatsApp to every
    server-mode role, not just field_crew, so any role might say "text
    David" and expect their own saved contact, not someone else's.
    """
    if user is not None:
        uname = (user.get('username') or user.get('id') or
                 user.get('name') or 'unknown').strip().lower()
        # Sanitise to a safe filename component
        import re as _rsan
        uname = _rsan.sub(r'[^a-z0-9_-]', '_', uname) or 'unknown'
        return _state_dir() / f"contacts_cache_{uname}.json"
    return _state_dir() / "contacts_cache.json"


def _contacts_cache_load(user: "dict | None" = None) -> dict:
    """Load the relevant contacts_cache.json for this user (see
    _CONTACTS_CACHE_PATH), returning {'contacts': {}} if missing."""
    try:
        p = _CONTACTS_CACHE_PATH(user)
        if p.exists():
            import json as _jsc
            data = _jsc.loads(p.read_text(encoding="utf-8")) or {}
            data.setdefault('contacts', {})
            return data
    except Exception:
        pass
    return {'contacts': {}}


def _contacts_cache_save(data: dict, user: "dict | None" = None) -> bool:
    """Save the relevant contacts_cache.json for this user. Atomic write."""
    try:
        import json as _jscs
        p = _CONTACTS_CACHE_PATH(user)
        p.parent.mkdir(parents=True, exist_ok=True)
        tmp = p.with_suffix(".json.tmp")
        tmp.write_text(_jscs.dumps(data, indent=2), encoding="utf-8")
        import os as _eos2
        _eos2.replace(str(tmp), str(p))
        return True
    except Exception:
        return False


def _contact_lookup(name_or_phone: str, user: "dict | None" = None) -> "dict | None":
    """Resolve a name or phone number to its contact record, scoped to the
    calling user (field_crew get their own private file in server mode;
    everyone else uses the shared/personal contacts_cache.json).
    Returns the record dict (with 'name' key added) or None if not found."""
    import re as _rclk
    data = _contacts_cache_load(user)
    contacts = data.get('contacts', {})

    digits = _rclk.sub(r'\D', '', name_or_phone)
    if len(digits) == 11 and digits[0] == '1':
        digits = digits[1:]

    key = name_or_phone.strip().lower()

    # Try exact name match first
    if key in contacts:
        rec = dict(contacts[key])
        rec['name'] = key
        return rec

    # Try phone number match across all contacts
    if len(digits) == 10:
        for nm, rec in contacts.items():
            rec_digits = _rclk.sub(r'\D', '', rec.get('phone', ''))
            if len(rec_digits) == 11 and rec_digits[0] == '1':
                rec_digits = rec_digits[1:]
            if rec_digits == digits:
                out = dict(rec)
                out['name'] = nm
                return out

    return None


def _contact_save(name: str, phone: str = "", email: str = "",
                   user: "dict | None" = None) -> dict:
    """Create or update a contact record for the calling user's scope
    (field_crew's own private file in server mode; shared/personal
    contacts_cache.json otherwise). Merges with any existing fields for
    that name so a partial update doesn't wipe other known info."""
    data = _contacts_cache_load(user)
    key = name.strip().lower()
    rec = data['contacts'].get(key, {})
    if phone.strip():
        import re as _rcs
        d = _rcs.sub(r'\D', '', phone)
        if len(d) == 11 and d[0] == '1':
            d = d[1:]
        rec['phone'] = d
    if email.strip():
        rec['email'] = email.strip()
    data['contacts'][key] = rec
    _contacts_cache_save(data, user)
    return rec


def _email_config_load() -> "dict | None":
    """Load email config from disk. Returns None if not configured.

    Accepts both SMTP configs (must have smtp_host) and Outlook configs
    (backend='outlook' — no smtp_host required).
    """
    try:
        if _EMAIL_CONFIG_PATH().exists():
            raw = json.loads(_EMAIL_CONFIG_PATH().read_text(encoding="utf-8"))
            if isinstance(raw, dict):
                # Outlook backend (or Outlook+SMTP) — valid without smtp_host
                if raw.get("backend") in ("outlook", "outlook+smtp") \
                        and raw.get("username"):
                    raw = dict(raw)
                    # No password to decode for Outlook configs
                    return raw
                # SMTP backend (or legacy config without 'backend' key)
                if raw.get("smtp_host"):
                    raw = dict(raw)
                    enc = raw.get("_password_b64", "")
                    if enc:
                        raw["password"] = _b64.b64decode(enc.encode()).decode("utf-8")
                    return raw
    except Exception as _e:
        _log.warning("email_config load failed: %s", _e)
    return None


def _lookup_customer_email(name_or_id: str, ctx=None) -> "str | None":
    """Look up a customer's email address from the customers table by name or ID.

    Matches CustomerID (CUST-####) exactly first, then falls back to a
    substring match against Company Name, First Name, Last Name, or Phone
    (case-insensitive). Returns the email string or None. Used by
    send_email()/send_alert() so any role can address customers by name
    without knowing their email.

    2026-09-13 fix: this was still fully openpyxl-based, opening the old
    .xlsx Job Tracker directly — the same class of bug just fixed in
    email_invoice()/text_invoice()/email_receipt()/text_receipt()'s
    shared _find_invoice_row(), found while porting those four. It had
    been silently unable to find any customer added after the SQLite
    migration. Also accepts `ctx` (optional, defaults to None so any
    external caller not passing it still works) and resolves the job
    database via _resolve_job_db_path(ctx, ...) like every other job tool —
    the one shared database for every user (R-046).

    v8.0.0 — enables customer email from the job spreadsheet.
    v9.2.0 — ported to the DB-backed customers table.
    """
    try:
        db_path = _resolve_job_db_path(ctx, "")
        if not db_path:
            return None
        import sqlite3 as _sqlite3_lce
        conn = _sqlite3_lce.connect(db_path)
        conn.row_factory = _sqlite3_lce.Row
        try:
            needle = name_or_id.strip()
            if not needle:
                return None
            row = conn.execute(
                "SELECT email FROM customers WHERE customer_id = ?", (needle,)
            ).fetchone()
            if row and row["email"]:
                return str(row["email"])
            like = f"%{needle.lower()}%"
            row = conn.execute(
                "SELECT email FROM customers WHERE "
                "(LOWER(company_name) LIKE ? OR LOWER(first_name) LIKE ? "
                "OR LOWER(last_name) LIKE ? OR LOWER(phone) LIKE ?) "
                "AND email IS NOT NULL AND email != '' LIMIT 1",
                (like, like, like, like),
            ).fetchone()
            if row and row["email"]:
                return str(row["email"])
        finally:
            conn.close()
    except Exception:
        pass
    return None


def _email_config_save(cfg: dict) -> bool:
    """Save email config to disk. Obfuscates password with base64."""
    try:
        _EMAIL_CONFIG_PATH().parent.mkdir(parents=True, exist_ok=True)
        out = dict(cfg)
        pw = out.pop("password", "")
        if pw:
            out["_password_b64"] = _b64.b64encode(pw.encode("utf-8")).decode()
        tmp = _EMAIL_CONFIG_PATH().with_suffix(".json.tmp")
        tmp.write_text(json.dumps(out, indent=2), encoding="utf-8")
        import os as _eos
        _eos.replace(str(tmp), str(_EMAIL_CONFIG_PATH()))
        return True
    except Exception as _e:
        _log.error("email_config save failed: %s", _e)
        return False


def _outlook_is_available() -> bool:
    """Return True if classic Outlook (with COM interface) is available.

    The NEW Outlook for Windows (olk.exe / Windows Store app, released 2023+)
    does NOT expose a COM interface — it raises REGDB_E_CLASSNOTREG (-2147221005)
    on every COM strategy.  This function intentionally returns False for the new
    Outlook because AI-Prowler's send_email / email_invoice tools require the COM
    interface to send silently in the background without user interaction.

    For new Outlook users, SMTP with an app password is the correct backend.

    Detection strategies (classic Outlook only):
    1. GetActiveObject  — safe; connects to an already-running Outlook instance
                          without launching anything. Returns True instantly.
    2. Registry probe   — safe; reads HKLM/HKCU App Paths for OUTLOOK.EXE.
                          Never launches any process. Explicitly excludes olk.exe.
    NOTE: Dispatch("Outlook.Application") is intentionally NOT used — it cold-starts
    the OUTLOOK.EXE process as a side effect, which conflicts with new Outlook (olk.exe)
    and causes the "Only one version of Outlook can run at a time" error on startup.
    """
    try:
        import win32com.client as _wc

        # Strategy 1 — GetActiveObject: connects to a RUNNING Outlook instance.
        # SAFE — never launches Outlook, only checks if it is already open.
        try:
            _app = _wc.GetActiveObject("Outlook.Application")
            _ = _app.Version
            return True
        except Exception:
            pass

        # ── Strategy 2 (Dispatch) intentionally REMOVED ──────────────────────
        # wc.Dispatch("Outlook.Application") cold-starts the Outlook COM server,
        # which actually LAUNCHES the OUTLOOK.EXE process as a side effect.
        # When the new Outlook (olk.exe) is also running, this triggers the
        # "Only one version of Outlook can run at a time" conflict error.
        # GetActiveObject (Strategy 1) and the registry probe (Strategy 3) are
        # sufficient to detect classic Outlook without launching it.
        # ─────────────────────────────────────────────────────────────────────

        # Strategy 3 — Registry probe: checks for OUTLOOK.EXE in App Paths.
        # SAFE — reads registry only, never launches any process.
        # Explicitly excludes olk.exe (new Outlook) which has no COM server.
        try:
            import winreg as _reg
            for _hive in (_reg.HKEY_LOCAL_MACHINE, _reg.HKEY_CURRENT_USER):
                try:
                    _k = _reg.OpenKey(
                        _hive,
                        r"SOFTWARE\Microsoft\Windows\CurrentVersion"
                        r"\App Paths\OUTLOOK.EXE")
                    _val, _ = _reg.QueryValueEx(_k, "")
                    if _val and "olk" not in _val.lower():
                        return True   # classic OUTLOOK.EXE registered
                except OSError:
                    pass
        except Exception:
            pass

        return False

    except ImportError:
        # win32com (pywin32) not installed
        return False


def _new_outlook_is_running() -> bool:
    """Return True if the new Outlook for Windows (olk.exe) is running.

    The new Outlook has no COM interface, so email must go via SMTP.
    This helper lets the GUI show an accurate status message.
    """
    try:
        import subprocess as _sp
        _r = _sp.run(
            'tasklist /FI "IMAGENAME eq olk.exe" /NH',
            capture_output=True, text=True, shell=True)
        return "olk.exe" in _r.stdout.lower()
    except Exception:
        return False


def _new_outlook_is_installed() -> bool:
    """Return True if the new Outlook for Windows (olk.exe) is installed."""
    try:
        import winreg as _reg, os as _os
        for _hive in (_reg.HKEY_LOCAL_MACHINE, _reg.HKEY_CURRENT_USER):
            try:
                _k = _reg.OpenKey(
                    _hive,
                    r"SOFTWARE\Microsoft\Windows\CurrentVersion"
                    r"\App Paths\olk.exe")
                _val, _ = _reg.QueryValueEx(_k, "")
                if _val and _os.path.exists(_val):
                    return True
            except (OSError, FileNotFoundError):
                pass
    except Exception:
        pass
    return False


def _send_via_outlook(to: str, subject: str, body: str,
                      attachment_path: "str | None" = None,
                      body_html: "str | None" = None,
                      reply_to: "str | None" = None,
                      sender_display: "str | None" = None,
                      from_account_email: "str | None" = None) -> tuple:
    """Send email through the local Outlook COM interface.

    Uses whichever Outlook account is set as default, or the account whose
    address matches from_account_email when multiple accounts are configured.
    Outlook does NOT need to be open — COM activates it in the background.
    No password is required; Outlook uses its cached credentials (including
    MS365 / Exchange OAuth tokens stored by Windows).

    Returns (ok: bool, message: str).
    """
    try:
        import win32com.client as _wc
        _app   = _wc.Dispatch("Outlook.Application")
        _ns    = _app.GetNamespace("MAPI")
        _mail  = _app.CreateItem(0)  # 0 = olMailItem

        _mail.To      = to
        _mail.Subject = subject

        # Choose the sending account when the user has multiple Outlook accounts
        # (personal + work, or multiple MS365 tenants).
        if from_account_email:
            _target = from_account_email.strip().lower()
            for _acct in _ns.Accounts:
                if _acct.SmtpAddress.lower() == _target:
                    _mail.SendUsingAccount = _acct
                    break

        # Body — prefer HTML; plain-text fallback
        if body_html:
            _mail.HTMLBody = body_html
        else:
            _mail.Body = body

        # Reply-To (used in server mode so replies go to the employee, not company)
        if reply_to:
            _mail.ReplyRecipients.Add(reply_to)

        # Optional attachment
        if attachment_path:
            _mail.Attachments.Add(attachment_path)

        _mail.Send()
        _log.info("Outlook email sent to %s subject=%r", to, subject)
        return (True, f"✅ Email sent to {to} via Outlook")

    except Exception as _oe:
        _log.warning("Outlook send failed: %s", _oe)
        return (False, f"❌ Outlook send failed: {_oe}")


def _send_smtp(to: str, subject: str, body: str,
               attachment_path: "str | None" = None,
               body_html: "str | None" = None,
               reply_to: "str | None" = None,
               sender_display: "str | None" = None,
               from_account_override: "str | None" = None) -> tuple:
    """Core email send. Returns (ok: bool, message: str). Uses stored config.

    from_account_override: optional email address to send FROM — Outlook backend
    only. Overrides the account saved in config for this one send. Ignored for
    SMTP (which has a single account by definition).
    Routes automatically based on email_config.json:
      • backend = "outlook"  → send via local Outlook COM (no password needed,
                               works with any account Outlook has configured,
                               including MS365 / Exchange / personal Outlook.com).
      • backend = "smtp"     → send via SMTP with app password (Gmail, Yahoo,
                               iCloud, custom servers, or Outlook when Outlook
                               is not installed on the PC).

    reply_to:       Optional Reply-To header (employee's personal email in
                    server mode so the customer's Reply goes to them directly).
    sender_display: Optional From display-name override (server mode:
                    "Jake Smith via ABC Cleaning").
    """
    cfg = _email_config_load()
    if not cfg:
        return (False, "Email not configured. Call configure_email() first.")

    backend = cfg.get("backend", "smtp")

    # ── Outlook backend (or Outlook-primary with SMTP fallback) ───────────
    if backend in ("outlook", "outlook+smtp"):
        # from_account_override (per-send) takes priority over saved config username
        from_acct     = (from_account_override or
                         cfg.get("username", "").strip() or None)
        smtp_fallback = backend == "outlook+smtp" or bool(
            cfg.get("smtp_host", "").strip())

        ok, msg = _send_via_outlook(
            to=to, subject=subject, body=body,
            attachment_path=attachment_path,
            body_html=body_html,
            reply_to=reply_to,
            sender_display=sender_display,
            from_account_email=from_acct,
        )
        if not ok and smtp_fallback:
            _log.warning(
                "Outlook send failed — falling back to SMTP: %s", msg)
            return _send_smtp_core(cfg, to, subject, body,
                                   attachment_path, body_html,
                                   reply_to, sender_display)
        return (ok, msg)

    # ── SMTP-only backend ─────────────────────────────────────────────────
    return _send_smtp_core(cfg, to, subject, body,
                           attachment_path, body_html,
                           reply_to, sender_display)


def _send_smtp_core(cfg: dict, to: str, subject: str, body: str,
                    attachment_path: "str | None" = None,
                    body_html: "str | None" = None,
                    reply_to: "str | None" = None,
                    sender_display: "str | None" = None) -> tuple:
    """Raw SMTP send using a pre-loaded config dict. Internal use only."""
    import smtplib
    import ssl as _ssl
    from email.mime.multipart import MIMEMultipart
    from email.mime.text import MIMEText
    from email.mime.base import MIMEBase
    from email import encoders as _enc

    smtp_host = cfg.get("smtp_host", "").strip()
    smtp_port = int(cfg.get("smtp_port", 587))
    username  = cfg.get("username", "").strip()
    password  = cfg.get("password", "")
    from_addr = cfg.get("from_address", username).strip() or username
    from_name = sender_display or cfg.get("from_name", "AI-Prowler").strip()
    use_tls   = cfg.get("use_tls", True)

    if not smtp_host or not username:
        return (False, "Incomplete email config — smtp_host and username required.")

    # Build message
    msg = MIMEMultipart("mixed")
    msg["Subject"] = subject
    msg["From"]    = f"{from_name} <{from_addr}>" if from_name else from_addr
    msg["To"]      = to

    if reply_to:
        msg["Reply-To"] = reply_to

    alt_part = MIMEMultipart("alternative")
    alt_part.attach(MIMEText(body, "plain", "utf-8"))
    if body_html:
        alt_part.attach(MIMEText(body_html, "html", "utf-8"))
    msg.attach(alt_part)

    if attachment_path:
        try:
            ap = Path(attachment_path)
            with open(ap, "rb") as _fh:
                part = MIMEBase("application", "octet-stream")
                part.set_payload(_fh.read())
            _enc.encode_base64(part)
            part.add_header("Content-Disposition",
                            f'attachment; filename="{ap.name}"')
            msg.attach(part)
        except Exception as _ae:
            return (False, f"Could not attach file: {_ae}")

    try:
        context = _ssl.create_default_context()
        # msg.as_string() — NOT .as_bytes(). smtplib.sendmail()'s msg arg
        # must be a str (bytes here broke email_invoice/email_receipt's
        # parsing of the sent message once routed through this shared fn).
        if smtp_port == 465:
            with smtplib.SMTP_SSL(smtp_host, smtp_port,
                                  context=context, timeout=20) as server:
                server.login(username, password)
                server.sendmail(from_addr, [to], msg.as_string())
        else:
            with smtplib.SMTP(smtp_host, smtp_port, timeout=20) as server:
                server.ehlo()
                if use_tls:
                    server.starttls(context=context)
                    server.ehlo()
                server.login(username, password)
                server.sendmail(from_addr, [to], msg.as_string())
        _log.info("SMTP email sent to %s subject=%r", to, subject)
        return (True, f"✅ Email sent to {to}")
    except smtplib.SMTPAuthenticationError:
        return (False,
                "❌ SMTP authentication failed — check username/password. "
                "For Gmail, use a 16-digit App Password (not your account password). "
                "Get one at: myaccount.google.com → Security → App passwords.")
    except smtplib.SMTPException as _se:
        return (False, f"❌ SMTP error: {_se}")
    except Exception as _ge:
        return (False, f"❌ Send failed: {_ge}")


def _email_allowed_for_user(user: "dict | None") -> tuple:
    """Gate configure_email / send_file / send_learnings_report to personal mode only.
    Returns (allowed: bool, reason: str). PURE.

    These email tools use personal SMTP credentials and are not appropriate for
    a shared company server. In server mode, field_crew may use send_email /
    send_alert via the separate _send_email_cap gate below.

    Personal mode (user=None): always allowed.
    Server mode (user is not None): always blocked (for these tools).
    """
    if user is None:
        return (True, "personal mode")
    return (False,
            "This email tool is only available in personal mode. "
            "In server mode each user should configure email on their own "
            "personal AI-Prowler install.")


def _send_email_cap(user: "dict | None") -> tuple:
    """Capability gate for send_email and send_alert in server mode. PURE.

    Personal mode (user=None): always allowed (personal SMTP, single user).
    Server mode (v8.0.0): ALL roles may send email — owner, manager, staff,
    and field_crew all have can_send_email=True in _ROLE_CAPS.

    Recipients in server mode: customers in the job spreadsheet (Customers
    sheet, Email column — matched by name/company/ID) OR registered server
    users (users.json, email field). Name-to-email resolution is handled
    in send_email / send_alert before the SMTP call.

    configure_email, send_file, and send_learnings_report remain personal-only
    regardless of this capability — use _email_allowed_for_user for those.

    Returns (allowed: bool, reason: str).
    """
    if user is None:
        return (True, "personal mode — email permitted")
    caps = _role_caps(user.get("role"))
    if caps.get("can_send_email"):
        return (True, f"role '{user.get('role')}' may send email in server mode")
    return (False,
            f"role '{user.get('role')}' cannot send email from the company server — "
            "use your personal AI-Prowler install for email.")


def _send_sms_cap(user: "dict | None") -> tuple:
    """Capability gate for send_sms in server mode. PURE.

    Personal mode (user=None): always allowed (single-user desktop install).
    Server mode: True for ALL roles — owner, manager, staff, and field_crew
    can all send SMS via the company's configured SMS provider (Twilio,
    SignalWire, or Vonage).

    Inbound replies ARE correctly attributed per user: check_sms_replies()
    reads from a local webhook-backed inbox (sms_inbox.json/sms_threads.json)
    and filters to only the threads the calling user personally sent — Mike
    will not see Karen's reply to Jake's text. See sms_inbox.py for details.

    Returns (allowed: bool, reason: str).
    """
    if user is None:
        return (True, "personal mode — SMS permitted")
    caps = _role_caps(user.get("role"))
    if caps.get("can_send_sms"):
        return (True, f"role '{user.get('role')}' may send SMS in server mode")
    return (False,
            f"role '{user.get('role')}' cannot send SMS from the company server — "
            "use your personal AI-Prowler install for SMS (Twilio).")


@mcp.tool()
def configure_email(username: str,
                    backend: str = "auto",
                    smtp_host: str = "",
                    smtp_port: int = 587,
                    password: str = "",
                    from_name: str = "AI-Prowler",
                    default_to: str = "",
                    ctx: Context = None) -> str:
    """
    Configure email for AI-Prowler. One-time setup — all other email tools
    use the saved config automatically after this.

    configure_email is personal-mode only — it sets YOUR email account.
    In server mode the admin configures a shared company SMTP account once
    via Settings, then send_email / send_alert work for every role.

    ── BACKENDS ──────────────────────────────────────────────────────────
    backend="auto"    (default) — detects whether Outlook is installed and
                      uses it automatically.  No password needed.  Falls
                      back to SMTP if Outlook is not found.

    backend="outlook" — send via the local Outlook application (Outlook
                      Desktop or Microsoft 365).  Works with any account
                      Outlook has configured, including Exchange, MS365,
                      Outlook.com, and personal accounts.  Outlook does NOT
                      need to be open.  No password is required — Windows
                      uses cached credentials / OAuth tokens.

    backend="smtp"    — send via SMTP with an app password.  Required when
                      Outlook is not installed, or for Gmail, Yahoo, iCloud,
                      Apple Mail, Zoho, or any custom mail server.
                      smtp_host and password are required for this backend.

    ── SMTP PROVIDERS (backend="smtp") ───────────────────────────────────
      • Gmail        : smtp.gmail.com  port 587  (16-digit App Password —
                       create at myaccount.google.com → Security → App passwords)
      • Outlook.com  : smtp-mail.outlook.com  port 587  (App Password)
      • Microsoft 365: smtp.office365.com     port 587  (App Password)
      • Yahoo        : smtp.mail.yahoo.com    port 587  (App Password)
      • iCloud       : smtp.mail.me.com       port 587  (App-Specific Password)
      • Zoho         : smtp.zoho.com          port 587  (App Password)
      • Any SMTP     : use your provider's documented host and port

    Args:
        username:   Your email address (used as From address and SMTP login).
        backend:    "auto" (default), "outlook", or "smtp".
        smtp_host:  SMTP server hostname — required for backend="smtp".
                    Auto-filled by the GUI when you type your email address.
        smtp_port:  SMTP port (default 587 STARTTLS; use 465 for SMTPS).
        password:   App password — required for backend="smtp".
                    NOT your account login password.
        from_name:  Display name in the From field (default: "AI-Prowler").
        default_to: Default recipient when no 'to' is given to send_email.
        ctx:        MCP context (injected automatically).

    Returns:
        Confirmation string, or an error if the config could not be saved.
    """
    _telemetry_increment_tool_count("configure_email")

    user = _current_user(ctx)
    allowed, why = _email_allowed_for_user(user)
    if not allowed:
        return f"❌ {why}"

    username  = (username or "").strip()
    smtp_host = (smtp_host or "").strip()
    backend   = (backend or "auto").strip().lower()

    if not username:
        return "❌ username (your email address) is required."
    if backend not in ("auto", "outlook", "smtp"):
        return "❌ backend must be 'auto', 'outlook', or 'smtp'."

    # ── Resolve "auto" ────────────────────────────────────────────────────
    if backend == "auto":
        backend = "outlook" if _outlook_is_available() else "smtp"

    # ── Outlook backend — no password needed ──────────────────────────────
    if backend == "outlook":
        if not _outlook_is_available():
            return (
                "❌ Outlook is not installed or not accessible on this PC.\n"
                "   Use backend='smtp' with an app password instead, or\n"
                "   install Microsoft Outlook and try again."
            )
        cfg = {
            "backend":      "outlook",
            "username":     username,
            "from_address": username,
            "from_name":    from_name.strip() or "AI-Prowler",
            "default_to":   default_to.strip() or username,
        }
        # Preserve any existing SMTP config as a fallback in case Outlook
        # becomes unavailable later (uninstalled, profile removed) —
        # including the app password itself. _email_config_save() does a
        # FULL FILE OVERWRITE with no merge against the existing file, so
        # any field not present in `cfg` here is gone from disk after this
        # call. The password is stored on disk as "_password_b64" (already
        # base64-obfuscated), not "password" — carrying it forward as-is
        # (not re-encoding it) avoids double-encoding while still
        # preserving it. Without this, every call to
        # configure_email(backend="outlook") silently deleted the real
        # SMTP app password — found via code review while designing this
        # tool's own E2E test, before ever running it against real config,
        # specifically because this is the same class of bug already found
        # and fixed once in the Settings GUI's _save_smtp_cfg() — a
        # separate code path that reaches the same email_config.json file
        # and had the identical flaw.
        existing = _email_config_load() or {}
        if existing.get("smtp_host"):
            cfg["smtp_host"] = existing["smtp_host"]
            cfg["smtp_port"] = existing.get("smtp_port", 587)
            if existing.get("_password_b64"):
                cfg["_password_b64"] = existing["_password_b64"]

        if not _email_config_save(cfg):
            return "❌ Could not save email config. Check disk permissions."

        # List all Outlook accounts so the user knows which one will send
        acct_lines = []
        try:
            import win32com.client as _wc
            _ns = _wc.Dispatch("Outlook.Application").GetNamespace("MAPI")
            for _a in _ns.Accounts:
                marker = " ← will use (matches username)" \
                         if _a.SmtpAddress.lower() == username.lower() else ""
                acct_lines.append(f"   • {_a.SmtpAddress}{marker}")
        except Exception:
            pass

        lines = [
            "✅ Email configured — Outlook backend.",
            f"   Sending as : {username}",
            f"   From name  : {cfg['from_name']}",
            "   Password   : not required (Outlook uses Windows cached credentials)",
        ]
        if acct_lines:
            lines.append("   Outlook accounts found:")
            lines.extend(acct_lines)
        lines += [
            "",
            "Outlook does not need to be open to send — it runs in the background.",
            "To test: call send_alert() or send_email() with a test message.",
        ]
        return "\n".join(lines)

    # ── SMTP backend ──────────────────────────────────────────────────────
    if not smtp_host:
        return (
            "❌ smtp_host is required for backend='smtp'.\n"
            "   Examples: smtp.gmail.com, smtp-mail.outlook.com,\n"
            "             smtp.office365.com, smtp.mail.yahoo.com"
        )
    if not password:
        return (
            "❌ password (app password) is required for backend='smtp'.\n"
            "   Use an App Password, not your account login password.\n"
            "   Gmail: myaccount.google.com → Security → App passwords\n"
            "   Microsoft: account.live.com/proofs/AppPassword\n"
            "   Yahoo: login.yahoo.com/account/security/app-passwords"
        )
    if smtp_port < 1 or smtp_port > 65535:
        return f"❌ smtp_port {smtp_port} is invalid (must be 1–65535)."

    cfg = {
        "backend":      "smtp",
        "smtp_host":    smtp_host,
        "smtp_port":    smtp_port,
        "username":     username,
        "password":     password,
        "from_address": username,
        "from_name":    from_name.strip() or "AI-Prowler",
        "default_to":   default_to.strip() or username,
        "use_tls":      smtp_port != 465,
    }

    if not _email_config_save(cfg):
        return "❌ Could not save email config. Check disk permissions."

    lines = [
        "✅ Email configured — SMTP backend.",
        f"   SMTP host  : {smtp_host}:{smtp_port}",
        f"   Account    : {username}",
        f"   From name  : {cfg['from_name']}",
    ]
    if default_to:
        lines.append(f"   Default to : {default_to}")
    lines += [
        "",
        "To test: call send_alert() or send_email() with a test message.",
    ]
    return "\n".join(lines)


@mcp.tool()
def list_outlook_accounts(ctx: Context = None) -> str:
    """
    List all email accounts configured in the local Microsoft Outlook installation.

    Use this when the Outlook backend is active and you want to know which accounts
    are available to send from, or to help the user choose one for a specific email.

    Returns a numbered list of SMTP addresses with a note showing which one is
    currently set as the default in AI-Prowler's config.

    Voice examples:
        "Which email accounts does Outlook have?"
        "What email addresses can I send from?"
        "Show me my Outlook accounts"

    Personal mode only — not available in server mode.
    """
    _telemetry_increment_tool_count("list_outlook_accounts")

    user = _current_user(ctx)
    if user is not None:
        return "❌ list_outlook_accounts is only available in personal mode."

    cfg          = _email_config_load() or {}
    saved_acct   = cfg.get("username", "").strip().lower()
    backend      = cfg.get("backend", "smtp")

    if backend not in ("outlook", "outlook+smtp"):
        return (
            "ℹ️  The Outlook backend is not currently active "
            f"(configured backend: '{backend}').\n"
            "To use Outlook accounts, run configure_email() with "
            "backend='outlook' or backend='outlook+smtp'."
        )

    if not _outlook_is_available():
        return (
            "❌ Classic Outlook (OUTLOOK.EXE) is not available on this machine.\n"
            "The New Outlook (olk.exe) has no COM interface — use SMTP instead."
        )

    try:
        import win32com.client as _wc
        # Try GetActiveObject first (Outlook already open — instant, no side effects).
        # Fall back to Dispatch (Outlook installed but not open — starts it silently
        # in the background just long enough to read accounts, same as _send_via_outlook).
        try:
            _app = _wc.GetActiveObject("Outlook.Application")
        except Exception:
            # Outlook not currently open — cold-start via Dispatch.
            # This is safe here because the user has explicitly asked to list accounts,
            # and Dispatch is only blocked from _outlook_is_available() to prevent
            # the conflict error at AI-Prowler startup (before the user has asked
            # anything). At this point the user has deliberately invoked the tool.
            _app = _wc.Dispatch("Outlook.Application")
        _ns   = _app.GetNamespace("MAPI")
        accts = [_a.SmtpAddress for _a in _ns.Accounts
                 if _a.SmtpAddress]
    except Exception as _e:
        return (f"❌ Could not enumerate Outlook accounts: {_e}\n"
                "Make sure classic Outlook (OUTLOOK.EXE) is installed.\n"
                "If the New Outlook (olk.exe) is also installed and running,\n"
                "close it first — only one version of Outlook can run at a time.")

    if not accts:
        return "⚠️  No email accounts found in Outlook."

    lines = ["Outlook accounts available to send from:\n"]
    for i, addr in enumerate(accts, 1):
        is_default = addr.strip().lower() == saved_acct
        marker     = "  ← current default" if is_default else ""
        lines.append(f"  {i}. {addr}{marker}")

    lines += [
        "",
        "To send from a specific account, use the from_account parameter:",
        f'  send_email(to="...", subject="...", body="...", '
        f'from_account="{accts[0]}")',
        "",
        "To change the default, call configure_email() with the desired address:",
        f'  configure_email(username="{accts[0]}", backend="outlook")',
    ]
    return "\n".join(lines)


@mcp.tool()
def send_email(to: str, subject: str, body: str,
               attachment_path: str = "",
               body_html: str = "",
               from_account: str = "",
               ctx: Context = None) -> str:
    """
    Send an email via the configured email backend (Outlook or SMTP).

    In server mode, any role (owner, manager, staff, field_crew) may email:
      • Other registered users of this server (by email address or name).
      • Customers listed in the job spreadsheet (by name, company, or CustomerID).
          The Customers sheet Email column is used — no need to know the address.

    Args:
        to:              Recipient email address, or a customer/user name to look
                         up automatically (e.g. "Torres", "Blue Wave Cafe",
                         "CUST-0003"). Leave blank to use the configured default_to.
        subject:         Email subject line.
        body:            Plain-text email body. Always used as the plain-text
                         part (and as the sole body if body_html is omitted).
        attachment_path: Optional — absolute path to a file in a tracked
                         read-allowlisted directory to attach to the email.
        body_html:       Optional — HTML version of the body. When provided,
                         the email is sent as multipart/alternative so HTML
                         mail clients render the formatted version instead of
                         showing raw tags, with `body` kept as the plain-text
                         fallback.
        from_account:    Optional — email address of the Outlook account to send
                         FROM when the Outlook backend is active and multiple
                         accounts are configured (e.g. "david@gmail.com" or
                         "david@yahoo.com"). Overrides the account saved in
                         Settings for this one send only. Has no effect when
                         using the SMTP backend. Use list_outlook_accounts() to
                         see all available accounts.
        ctx:             MCP context (injected automatically)

    Returns:
        "✅ Email sent to <address>" on success, or an error string.

    Voice examples:
        "Email Torres that his job is confirmed for Saturday"
        "Send the Blue Wave Cafe invoice to the customer"
        "Email Jake a summary of today's jobs"
        "Send Maria the updated schedule"
        "Email the Torres invoice from my Yahoo account"
        "Send this from my Gmail, not my work email"
    """
    _telemetry_increment_tool_count("send_email")

    # Resolve user early so contact-name lookups can be scoped correctly
    # (field_crew get their own private contacts_cache_<username>.json).
    user = _current_user(ctx)

    cfg = _email_config_load()
    if not cfg:
        return ("❌ Email not configured. "
                "Call configure_email() first with your SMTP settings.")

    to = (to or "").strip() or cfg.get("default_to", "").strip()
    if not to:
        return "❌ No recipient address. Provide a 'to' address or name, or set default_to via configure_email()."

    # v8.0.0: if 'to' doesn't look like an email address, try to resolve it
    # from the Customers sheet (by name/company/ID), users.json (by name),
    # or the personal contacts_cache.json (by name) — in that order.
    if '@' not in to:
        _resolved = _lookup_customer_email(to, ctx=ctx)
        if _resolved:
            to = _resolved
        else:
            # Try registered users by name
            try:
                _ud = _load_users()
                if _ud:
                    _needle = to.lower()
                    for _u in (_ud.get('users') or {}).values():
                        if isinstance(_u, dict):
                            if _needle in (_u.get('name') or '').lower():
                                _em = (_u.get('email') or '').strip()
                                if _em:
                                    to = _em
                                    break
            except Exception:
                pass
        if '@' not in to:
            # Try personal contacts_cache.json by name
            try:
                _pc = _contact_lookup(to, user)
                if _pc and _pc.get('email'):
                    to = _pc['email']
            except Exception:
                pass
        if '@' not in to:
            return (
                f"❌ Could not resolve '{to}' to an email address.\n"
                "Check that the name matches a customer in the Customers sheet, "
                "a registered user in the Admin tab, or a saved contact "
                "(\"<name>'s email is ...\"), and that their Email is filled in."
            )

    subject = subject.strip()
    if not subject:
        return "❌ subject is required."
    if not body.strip():
        return "❌ body is required."

    # v8.0.0: all server-mode roles may send email via the company SMTP.
    allowed, why = _send_email_cap(user)
    if not allowed:
        return f"❌ {why}"

    # Server mode: personalise From display name and set Reply-To to the
    # employee's registered email so the recipient can reply directly to them.
    reply_to       = None
    sender_display = None
    if user is not None:
        emp_email = (user.get("email") or "").strip()
        emp_name  = (user.get("name")  or "").strip()
        if emp_email:
            reply_to = (f"{emp_name} <{emp_email}>"
                        if emp_name else emp_email)
        if emp_name:
            cfg_name = (_email_config_load() or {}).get("from_name", "")
            sender_display = (f"{emp_name} via {cfg_name}"
                              if cfg_name else emp_name)

    # Resolve optional attachment
    attach = None
    if attachment_path and attachment_path.strip():
        resolved_attach, err = _resolve_allowlisted_path(attachment_path.strip())
        if err:
            return f"❌ Attachment: {err}"
        attach = resolved_attach

    # R-053: server mode ignores from_account — every user sends from the
    # company account chosen in Settings → Email Configuration. With an
    # Outlook backend the server's Outlook profile may hold other mailboxes
    # (the owner's own, say) that a signed-in employee must not send from.
    _from_override = (from_account.strip() or None) if user is None else None
    ok, msg = _send_smtp(to, subject, body, attachment_path=attach,
                         body_html=(body_html.strip() or None),
                         reply_to=reply_to, sender_display=sender_display,
                         from_account_override=_from_override)
    return msg


@mcp.tool()
def send_alert(message: str, to: str = "",
               ctx: Context = None) -> str:
    """
    Send a quick one-line alert email. Subject is auto-generated from the
    message. Great for short voice-commanded notifications.

    In server mode, field crew may alert:
      • Other registered users of this server (by email address or name).
      • Customers listed in the job spreadsheet (by name, company, or CustomerID).

    Args:
        message: The alert text. Keep it concise — it becomes both the
                 subject (truncated) and the body.
        to:      Recipient email address, or a customer/user name to look up
                 (e.g. "Torres", "Blue Wave Cafe"). Leave blank for default_to.
        ctx:     MCP context (injected automatically)

    Returns:
        "✅ Alert sent to <address>" on success, or an error string.

    Voice examples:
        "Alert Torres that we're 20 minutes away"
        "Ping the Blue Wave Cafe that we're done"
        "Alert Jake that I'm running late"
        "Ping the owner that the gate code isn't working"
    """
    _telemetry_increment_tool_count("send_alert")

    cfg = _email_config_load()
    if not cfg:
        return ("❌ Email not configured. "
                "Call configure_email() first with your SMTP settings.")

    to = (to or "").strip() or cfg.get("default_to", "").strip()
    if not to:
        return "❌ No recipient. Provide a 'to' address or name, or set default_to via configure_email()."

    # v8.0.0: name → email resolution (Customers sheet first, then users.json)
    if '@' not in to:
        _resolved = _lookup_customer_email(to, ctx=ctx)
        if _resolved:
            to = _resolved
        else:
            try:
                _ud = _load_users()
                if _ud:
                    _needle = to.lower()
                    for _u in (_ud.get('users') or {}).values():
                        if isinstance(_u, dict):
                            if _needle in (_u.get('name') or '').lower():
                                _em = (_u.get('email') or '').strip()
                                if _em:
                                    to = _em
                                    break
            except Exception:
                pass
        if '@' not in to:
            return (
                f"❌ Could not resolve '{to}' to an email address.\n"
                "Check that the name matches a customer in the Customers sheet "
                "or a registered user in the Admin tab, and that their Email is filled in."
            )

    message = message.strip()
    if not message:
        return "❌ message is required."

    # v8.0.0: all server-mode roles may send alerts via the company SMTP.
    user = _current_user(ctx)
    allowed, why = _send_email_cap(user)
    if not allowed:
        return f"❌ {why}"

    # Server mode: personalise From display name and set Reply-To to employee's email.
    reply_to       = None
    sender_display = None
    if user is not None:
        emp_email = (user.get("email") or "").strip()
        emp_name  = (user.get("name")  or "").strip()
        if emp_email:
            reply_to = (f"{emp_name} <{emp_email}>"
                        if emp_name else emp_email)
        if emp_name:
            cfg_name = (_email_config_load() or {}).get("from_name", "")
            sender_display = (f"{emp_name} via {cfg_name}"
                              if cfg_name else emp_name)

    # Subject: first 80 chars of message
    subject = f"AI-Prowler Alert: {message[:80]}"
    import datetime as _dt2
    body = (f"{message}\n\n"
            f"— Sent by AI-Prowler at "
            f"{_dt2.datetime.now().strftime('%Y-%m-%d %H:%M')}")

    ok, msg = _send_smtp(to, subject, body,
                         reply_to=reply_to, sender_display=sender_display)
    return msg


@mcp.tool()
def send_file(to: str, filepath: str,
              subject: str = "", body: str = "",
              ctx: Context = None) -> str:
    """
    Send any file from a tracked directory as an email attachment.

    Args:
        to:       Recipient email address. Leave blank for default_to.
        filepath: Absolute path to the file to send (must be in the read
                  allowlist). Any file type is supported.
        subject:  Email subject. Auto-generated from filename if blank.
        body:     Email body text. Auto-generated if blank.
        ctx:      MCP context (injected automatically)

    Returns:
        "✅ Email sent" or an error string.

    Voice examples:
        "Email the Q3 report to the boss"
        "Send the updated config to john@company.com"
        "Email the job tracker spreadsheet to myself"
    """
    _telemetry_increment_tool_count("send_file")

    cfg = _email_config_load()
    if not cfg:
        return ("❌ Email not configured. "
                "Call configure_email() first.")

    to = (to or "").strip() or cfg.get("default_to", "").strip()
    if not to:
        return "❌ No recipient address."

    resolved, err = _resolve_allowlisted_path(filepath.strip())
    if err:
        return f"❌ {err}"

    fname = Path(resolved).name
    if not subject.strip():
        subject = f"AI-Prowler: {fname}"
    if not body.strip():
        import datetime as _dt3
        body = (f"File attached: {fname}\n\n"
                f"Sent by AI-Prowler at "
                f"{_dt3.datetime.now().strftime('%Y-%m-%d %H:%M')}")

    # send_file: personal-mode only (arbitrary file attachment = exfiltration risk).
    user = _current_user(ctx)
    allowed, why = _email_allowed_for_user(user)
    if not allowed:
        return f"❌ {why}"

    ok, msg = _send_smtp(to, subject, body, attachment_path=resolved)
    return msg


